    #[test]
    fn straight_line_ir_body_requires_entry_rooted_terminating_return() {
        use trust_types::{BasicBlock, BlockId, Operand, Place, Rvalue, Statement, Terminator};

        let ret = || Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
            span: Default::default(),
        };
        let positive = direct_return_probe(
            "entry_rooted_return",
            i32_ty(),
            vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Goto(BlockId(1)),
                },
                BasicBlock { id: BlockId(1), stmts: vec![ret()], terminator: Terminator::Return },
            ],
            1,
        );
        assert!(
            straight_line_ir_body(&positive).is_some(),
            "load-bearing control: the entry-rooted acyclic path reaches its one Return"
        );

        let self_loop = direct_return_probe(
            "assigned_self_loop",
            i32_ty(),
            vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![ret()],
                terminator: Terminator::Goto(BlockId(0)),
            }],
            1,
        );
        assert!(
            straight_line_ir_body(&self_loop).is_none(),
            "an `_0` assignment in a diverging entry self-loop is not a returned value"
        );

        let disconnected = direct_return_probe(
            "disconnected_return_island",
            i32_ty(),
            vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Goto(BlockId(0)),
                },
                BasicBlock { id: BlockId(1), stmts: vec![ret()], terminator: Terminator::Return },
            ],
            1,
        );
        assert!(
            straight_line_ir_body(&disconnected).is_none(),
            "a disconnected assignment/Return island cannot define a diverging entry's result"
        );
    }

    #[test]
    fn straight_line_ir_body_rejects_float_div_on_int_carrier() {
        use trust_types::{
            BasicBlock, BinOp, BlockId, Operand, Place, Rvalue, Statement, Terminator, Ty,
        };

        let div_body = |ty: Ty| {
            direct_return_probe(
                "typed_div",
                ty,
                vec![BasicBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Div,
                            Operand::Copy(Place::local(1)),
                            Operand::Copy(Place::local(2)),
                        ),
                        span: Default::default(),
                    }],
                    terminator: Terminator::Return,
                }],
                2,
            )
        };
        assert!(
            straight_line_ir_body(&div_body(i32_ty())).is_some(),
            "load-bearing control: an Int division remains on the Int carrier"
        );
        assert!(
            straight_line_ir_body(&div_body(Ty::Float { width: 64 })).is_none(),
            "Float division must not be reinterpreted as trust-ir Int.div"
        );
    }

    #[test]
    fn straight_line_ir_body_chain_rejects_float_values_on_int_carrier() {
        use trust_types::{
            BasicBlock, BinOp, BlockId, Operand, Place, Rvalue, Statement, Terminator, Ty,
        };

        let div_then_return = |ty: Ty| {
            assignment_typing_function(
                "typed_div_chain",
                vec![ty.clone(), ty.clone(), ty.clone(), ty],
                vec![BasicBlock {
                    id: BlockId(0),
                    stmts: vec![
                        Statement::Assign {
                            place: Place::local(3),
                            rvalue: Rvalue::BinaryOp(
                                BinOp::Div,
                                Operand::Copy(Place::local(1)),
                                Operand::Copy(Place::local(2)),
                            ),
                            span: Default::default(),
                        },
                        Statement::Assign {
                            place: Place::local(0),
                            rvalue: Rvalue::Use(Operand::Copy(Place::local(3))),
                            span: Default::default(),
                        },
                    ],
                    terminator: Terminator::Return,
                }],
                2,
            )
        };
        assert!(
            straight_line_ir_body_chain(&div_then_return(i32_ty())).is_some(),
            "load-bearing control: an Int-valued temp chain remains representable"
        );
        assert!(
            straight_line_ir_body_chain(&div_then_return(Ty::Float { width: 64 })).is_none(),
            "a Float return chain must not be reinterpreted as trust-ir Int operations"
        );

        // Stronger parity probe: a Bool result does not make a Float intermediate
        // admissible.  This body is MIR-type-correct, so the production assignment-
        // typing gate cannot mask a carrier bug in the chain recognizer.
        let float = Ty::Float { width: 64 };
        let float_compare = assignment_typing_function(
            "float_div_then_compare_chain",
            vec![Ty::Bool, float.clone(), float.clone(), float],
            vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![
                    Statement::Assign {
                        place: Place::local(3),
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Div,
                            Operand::Copy(Place::local(1)),
                            Operand::Copy(Place::local(2)),
                        ),
                        span: Default::default(),
                    },
                    Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Eq,
                            Operand::Copy(Place::local(3)),
                            Operand::Copy(Place::local(1)),
                        ),
                        span: Default::default(),
                    },
                ],
                terminator: Terminator::Return,
            }],
            2,
        );
        assert!(crate::assignment_types::all_assignments_match(&float_compare.body));
        assert!(straight_line_ir_body_chain(&float_compare).is_none());
        assert!(!straight_line_chain_fully_faithful_via_trustir(&float_compare));
    }

    #[test]
    fn straight_line_ir_checked_temp_must_dominate_field_use() {
        use trust_types::{
            BasicBlock, BinOp, BlockId, Operand, Place, Projection, Rvalue, Statement, Terminator,
            Ty,
        };

        let return_from_field = Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Use(Operand::Copy(Place {
                local: 3,
                projections: vec![Projection::Field(0)],
            })),
            span: Default::default(),
        };
        let define_checked = Statement::Assign {
            place: Place::local(3),
            rvalue: Rvalue::CheckedBinaryOp(
                BinOp::Add,
                Operand::Copy(Place::local(1)),
                Operand::Copy(Place::local(2)),
            ),
            span: Default::default(),
        };
        let mut func = assignment_typing_function(
            "checked_temp_order",
            vec![i32_ty(), i32_ty(), i32_ty(), Ty::Tuple(vec![i32_ty(), Ty::Bool])],
            vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![return_from_field.clone(), define_checked.clone()],
                terminator: Terminator::Return,
            }],
            2,
        );
        assert!(
            straight_line_ir_body(&func).is_none(),
            "a checked tuple defined after `_0 := tuple.0` must fail closed"
        );
        func.body.blocks[0].stmts = vec![define_checked, return_from_field];
        assert!(
            straight_line_ir_body(&func).is_some(),
            "the same sole checked definition before its field use remains modeled"
        );
    }

    #[test]
    fn straight_line_ir_cast_temps_must_dominate_exact_uses() {
        use trust_types::{BasicBlock, BlockId, Operand, Place, Rvalue, Statement, Terminator, Ty};

        let i64_ty = Ty::Int { width: 64, signed: true };
        let cast_return = Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Cast(Operand::Copy(Place::local(2)), i64_ty.clone()),
            span: Default::default(),
        };
        let define_temp = Statement::Assign {
            place: Place::local(2),
            rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
            span: Default::default(),
        };
        let mut widening = assignment_typing_function(
            "widening_cast_temp_order",
            vec![i64_ty, i32_ty(), i32_ty()],
            vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![cast_return.clone(), define_temp.clone()],
                terminator: Terminator::Return,
            }],
            1,
        );
        assert!(
            straight_line_ir_body(&widening).is_none(),
            "a globally unique cast temp defined after `_0 := Cast(temp)` must fail closed"
        );
        widening.body.blocks[0].stmts = vec![define_temp, cast_return];
        assert!(
            straight_line_ir_body(&widening).is_some(),
            "the same widening source defined before its exact cast use remains modeled"
        );

        let mut narrowed = shr_narrowed_cast_function(44, false);
        // `_2 := Shr(..)` is statement 1 and `_0 := Cast(_2)` statement 2.
        // Put the cast first: the whole-body scan used to recover the later Shr.
        narrowed.body.blocks[0].stmts.swap(1, 2);
        assert!(
            straight_line_ir_body(&narrowed).is_none(),
            "the narrowing width fact cannot be imported from a later shift definition"
        );
    }

    #[test]
    fn local_write_completeness_rejects_projected_call_destination() {
        use trust_types::{
            BasicBlock, BlockId, ConstValue, Operand, Place, Projection, Rvalue, Statement,
            Terminator,
        };

        let mut call_defined = direct_return_probe(
            "sole_call_definition",
            i32_ty(),
            vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::Call {
                        func: "core::ptr::const_ptr::<impl *const T>::offset".into(),
                        args: vec![
                            Operand::Copy(Place::local(1)),
                            Operand::Constant(ConstValue::Int(1)),
                        ],
                        dest: Place::local(0),
                        target: Some(BlockId(1)),
                        unwind: UnwindEdge::Unreachable,
                        span: Default::default(),
                        atomic: None,
                        is_unsafe_sig: false,
                        is_foreign: false,
                    },
                },
                BasicBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            1,
        );
        assert!(local_has_only_one_bare_call_destination(&call_defined.body, 0));
        assert!(find_ptr_arith_call(0, &call_defined.body, BlockId(1), None).is_some());
        call_defined.body.blocks[1].stmts.push(Statement::Assign {
            place: Place::local(0),
            rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
            span: Default::default(),
        });
        assert!(!local_has_only_one_bare_call_destination(&call_defined.body, 0));
        assert!(find_ptr_arith_call(0, &call_defined.body, BlockId(1), None).is_none());

        let func = direct_return_probe(
            "projected_call_write",
            i32_ty(),
            vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
                        span: Default::default(),
                    }],
                    terminator: Terminator::Call {
                        func: "helper".into(),
                        args: vec![],
                        dest: Place { local: 0, projections: vec![Projection::Field(0)] },
                        target: Some(BlockId(1)),
                        unwind: UnwindEdge::Unreachable,
                        span: Default::default(),
                        atomic: None,
                        is_unsafe_sig: false,
                        is_foreign: false,
                    },
                },
                BasicBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            1,
        );
        assert!(
            !local_has_only_n_bare_assignments(&func.body, 0, 1),
            "a projected Call destination is an additional base-local write"
        );
        assert!(
            !local_has_at_most_n_bare_assignments(&func.body, 0, 2),
            "an at-most gate must also reject the projected Call destination"
        );
        assert!(!local_soundly_resolvable(&func.body, 0));
        assert!(
            resolve_temp_copy(0, &func.body, BlockId(1), None).is_none(),
            "a transparent-copy chase must not ignore the projected Call overwrite"
        );
        assert!(straight_line_ir_body(&func).is_none());
    }

    #[test]
    fn complete_local_effect_gates_reject_aliases_and_retag() {
        use trust_types::{
            BasicBlock, BlockId, ConstValue, Operand, Place, Rvalue, Statement, Terminator, Ty,
        };

        let make_assignment_body = |alias: Rvalue| {
            assignment_typing_function(
                "aliased_assignment_history",
                vec![i32_ty(), i32_ty(), Ty::Ref { mutable: true, inner: Box::new(i32_ty()) }],
                vec![BasicBlock {
                    id: BlockId(0),
                    stmts: vec![
                        Statement::Assign {
                            place: Place::local(1),
                            rvalue: Rvalue::Use(Operand::Constant(ConstValue::Int(7))),
                            span: Default::default(),
                        },
                        Statement::Assign {
                            place: Place::local(2),
                            rvalue: alias,
                            span: Default::default(),
                        },
                    ],
                    terminator: Terminator::Return,
                }],
                0,
            )
        };
        for alias in [
            Rvalue::Ref { mutable: true, place: Place::local(1) },
            Rvalue::AddressOf(true, Place::local(1)),
        ] {
            let func = make_assignment_body(alias);
            assert!(
                !local_has_only_n_bare_assignments(&func.body, 1, 1),
                "a mutable alias source invalidates an otherwise sole bare assignment"
            );
            assert!(!local_has_at_most_n_bare_assignments(&func.body, 1, 1));
        }

        // The alias source must be inspected even when the same statement's
        // destination is also the tracked local (`_1 := &mut _1`).
        let self_alias = assignment_typing_function(
            "self_alias_assignment_history",
            vec![i32_ty(), i32_ty()],
            vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(1),
                    rvalue: Rvalue::Ref { mutable: true, place: Place::local(1) },
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            }],
            0,
        );
        assert!(!local_has_only_n_bare_assignments(&self_alias.body, 1, 1));

        let retagged = assignment_typing_function(
            "retagged_assignment_history",
            vec![i32_ty(), i32_ty()],
            vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![
                    Statement::Assign {
                        place: Place::local(1),
                        rvalue: Rvalue::Use(Operand::Constant(ConstValue::Int(7))),
                        span: Default::default(),
                    },
                    Statement::Retag { place: Place::local(1) },
                ],
                terminator: Terminator::Return,
            }],
            0,
        );
        assert!(!local_has_only_n_bare_assignments(&retagged.body, 1, 1));

        let call_with_alias = assignment_typing_function(
            "aliased_call_history",
            vec![i32_ty(), i32_ty(), Ty::Ref { mutable: true, inner: Box::new(i32_ty()) }],
            vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(2),
                        rvalue: Rvalue::AddressOf(true, Place::local(1)),
                        span: Default::default(),
                    }],
                    terminator: Terminator::Call {
                        func: "helper".into(),
                        args: vec![],
                        dest: Place::local(1),
                        target: Some(BlockId(1)),
                        unwind: UnwindEdge::Unreachable,
                        span: Default::default(),
                        atomic: None,
                        is_unsafe_sig: false,
                        is_foreign: false,
                    },
                },
                BasicBlock { id: BlockId(1), stmts: vec![], terminator: Terminator::Return },
            ],
            0,
        );
        assert!(
            !local_has_only_one_bare_call_destination(&call_with_alias.body, 1),
            "a sole Call destination is not a complete definition after mutable aliasing"
        );
        let mut call_with_retag = call_with_alias;
        call_with_retag.body.blocks[0].stmts = vec![Statement::Retag { place: Place::local(1) }];
        assert!(
            !local_has_only_one_bare_call_destination(&call_with_retag.body, 1),
            "Retag invalidates an otherwise sole Call destination definition"
        );
    }

    #[test]
    fn loop_temp_copy_resolution_is_dominating_and_cycle_bounded() {
        use trust_types::{
            BasicBlock, BinOp, BlockId, ConstValue, Operand, Place, Rvalue, Statement, Terminator,
        };

        let var_of_param = |local: usize| (local == 1).then_some(0);
        let mut ordered = assignment_typing_function(
            "loop_temp_order",
            vec![i32_ty(), i32_ty(), i32_ty(), i32_ty()],
            vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![
                    Statement::Assign {
                        place: Place::local(3),
                        rvalue: Rvalue::BinaryOp(
                            BinOp::Add,
                            Operand::Copy(Place::local(2)),
                            Operand::Constant(ConstValue::Int(1)),
                        ),
                        span: Default::default(),
                    },
                    Statement::Assign {
                        place: Place::local(2),
                        rvalue: Rvalue::Use(Operand::Copy(Place::local(1))),
                        span: Default::default(),
                    },
                ],
                terminator: Terminator::Return,
            }],
            1,
        );
        let temp = Operand::Copy(Place::local(2));
        assert_eq!(
            sem_operand_for_loop(&temp, &ordered.body, &var_of_param, BlockId(0), Some(0)),
            None,
            "a sole temp definition after its exact use must not be chased"
        );
        assert!(resolve_temp_copy(2, &ordered.body, BlockId(0), Some(0)).is_none());
        ordered.body.blocks[0].stmts.swap(0, 1);
        assert_eq!(
            sem_operand_for_loop(&temp, &ordered.body, &var_of_param, BlockId(0), Some(1)),
            Some(crate::mirsem::SemOperand::Var(0)),
            "the same definition before the use remains a transparent parameter copy"
        );

        let cyclic = assignment_typing_function(
            "loop_temp_self_cycle",
            vec![i32_ty(), i32_ty(), i32_ty(), i32_ty()],
            vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![
                    Statement::Assign {
                        place: Place::local(2),
                        rvalue: Rvalue::Use(Operand::Copy(Place::local(2))),
                        span: Default::default(),
                    },
                    Statement::Assign {
                        place: Place::local(3),
                        rvalue: Rvalue::Use(Operand::Copy(Place::local(2))),
                        span: Default::default(),
                    },
                ],
                terminator: Terminator::Return,
            }],
            1,
        );
        assert_eq!(
            sem_operand_for_loop(
                &Operand::Copy(Place::local(2)),
                &cyclic.body,
                &var_of_param,
                BlockId(0),
                Some(1),
            ),
            None,
            "a transparent-copy self-cycle must fail closed within the bounded chase"
        );
    }

    #[test]
    fn ptr_arith_call_must_dominate_exact_commit_site() {
        use trust_types::{
            BasicBlock, BlockId, ConstValue, Operand, Place, Rvalue, Statement, Terminator,
        };

        let ptr_call = |target| Terminator::Call {
            func: "core::ptr::const_ptr::<impl *const T>::offset".into(),
            args: vec![Operand::Copy(Place::local(1)), Operand::Constant(ConstValue::Int(1))],
            dest: Place::local(2),
            target: Some(target),
            unwind: UnwindEdge::Unreachable,
            span: Default::default(),
            atomic: None,
            is_unsafe_sig: false,
            is_foreign: false,
        };
        let commit = Statement::Assign {
            place: Place::local(1),
            rvalue: Rvalue::Use(Operand::Copy(Place::local(2))),
            span: Default::default(),
        };
        let positive = assignment_typing_function(
            "dominating_ptr_call",
            vec![i32_ty(), i32_ty(), i32_ty()],
            vec![
                BasicBlock { id: BlockId(0), stmts: vec![], terminator: ptr_call(BlockId(1)) },
                BasicBlock {
                    id: BlockId(1),
                    stmts: vec![commit.clone()],
                    terminator: Terminator::Return,
                },
            ],
            1,
        );
        assert!(find_ptr_arith_call(2, &positive.body, BlockId(1), Some(0)).is_some());

        let sibling = assignment_typing_function(
            "sibling_ptr_call",
            vec![i32_ty(), i32_ty(), i32_ty()],
            vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![],
                    terminator: Terminator::SwitchInt {
                        discr: Operand::Constant(ConstValue::Bool(true)),
                        targets: vec![(0, BlockId(1))],
                        otherwise: BlockId(2),
                        exhaustive_enum_unreachable: false,
                        span: Default::default(),
                    },
                },
                BasicBlock { id: BlockId(1), stmts: vec![], terminator: ptr_call(BlockId(3)) },
                BasicBlock {
                    id: BlockId(2),
                    stmts: vec![commit],
                    terminator: Terminator::Goto(BlockId(3)),
                },
                BasicBlock { id: BlockId(3), stmts: vec![], terminator: Terminator::Return },
            ],
            1,
        );
        assert!(local_has_only_one_bare_call_destination(&sibling.body, 2));
        assert!(
            find_ptr_arith_call(2, &sibling.body, BlockId(2), Some(0)).is_none(),
            "a unique ptr call in a sibling arm cannot define the commit's consumed temp"
        );
    }

    #[test]
    fn untouched_return_loop_gates_reject_call_destination_overwrite() {
        use trust_types::{BasicBlock, BlockId, Place, Terminator};

        let append_return_overwrite = |func: &mut VerifiableFunction| {
            let return_id =
                BlockId(func.body.blocks.iter().map(|block| block.id.0).max().expect("blocks") + 1);
            let return_block = func
                .body
                .blocks
                .iter_mut()
                .find(|block| matches!(block.terminator, Terminator::Return))
                .expect("one return block");
            return_block.terminator = Terminator::Call {
                func: "helper".into(),
                args: vec![],
                dest: Place::local(0),
                target: Some(return_id),
                unwind: UnwindEdge::Unreachable,
                span: Default::default(),
                atomic: None,
                is_unsafe_sig: false,
                is_foreign: false,
            };
            func.body.blocks.push(BasicBlock {
                id: return_id,
                stmts: vec![],
                terminator: Terminator::Return,
            });
        };

        let loop_path = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("fixtures/real-spec-corpus/loop_keep_zero.json");
        let mut single: VerifiableFunction =
            serde_json::from_slice(&std::fs::read(loop_path).expect("loop fixture"))
                .expect("parse loop fixture");
        assert!(extract_loop_function(&single).is_some(), "load-bearing single-loop control");
        append_return_overwrite(&mut single);
        assert_eq!(local_write_count(&single.body, 0), 1, "the old bare scan misses Call dest");
        assert!(extract_loop_function(&single).is_none());

        let nested_path =
            Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/nested-corpus/nested.json");
        let mut nested: VerifiableFunction =
            serde_json::from_slice(&std::fs::read(nested_path).expect("nested fixture"))
                .expect("parse nested fixture");
        assert!(
            extract_nested_loop_function(&nested).is_some(),
            "load-bearing nested-loop control"
        );
        append_return_overwrite(&mut nested);
        assert_eq!(local_write_count(&nested.body, 0), 1, "the old bare scan misses Call dest");
        assert!(extract_nested_loop_function(&nested).is_none());
    }

    fn scalar_sentinel_select_fixture() -> VerifiableFunction {
        let directory = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("fixtures/cmp-mono-select-2026-07-16/dumps");
        for entry in std::fs::read_dir(&directory)
            .unwrap_or_else(|error| panic!("read {}: {error}", directory.display()))
        {
            let path = entry.expect("read fixture entry").path();
            if path.extension().and_then(|extension| extension.to_str()) != Some("json") {
                continue;
            }
            let bytes = std::fs::read(&path)
                .unwrap_or_else(|error| panic!("read {}: {error}", path.display()));
            let function: VerifiableFunction = serde_json::from_slice(&bytes)
                .unwrap_or_else(|error| panic!("parse {}: {error}", path.display()));
            if function.def_path == "<u8 as std::cmp::Ord>::min" {
                return function;
            }
        }
        panic!("missing <u8 as std::cmp::Ord>::min fixture in {}", directory.display());
    }

    fn assert_scalar_select_production_gate_declines(label: &str, function: &VerifiableFunction) {
        assert!(
            !diagnose_fully_faithful_gate(function, &Default::default()).fully_faithful,
            "{label}: the complete production gate must decline"
        );
    }

    /// Production-gate coverage for the scalar sentinel-select lane. The
    /// recognizer's local negatives are necessary but insufficient: another arm
    /// in the top-level disjunction must not accidentally re-admit a forged body.
    #[test]
    fn scalar_sentinel_select_production_gate_is_fail_closed() {
        use trust_types::{
            AtomicOpKind, AtomicOperation, AtomicOrdering, BasicBlock, BlockId, ConstValue,
            Operand, Place, Rvalue, Statement, Terminator,
        };

        let base = scalar_sentinel_select_fixture();
        let diagnosis = diagnose_fully_faithful_gate(&base, &Default::default());
        assert!(diagnosis.via_ir_shape, "the exact real leaf must reach the trust-ir lane");
        assert!(diagnosis.fully_faithful, "the exact real leaf must certify");

        let mut same_arm = base.clone();
        let returned_params = same_arm
            .body
            .blocks
            .iter()
            .flat_map(|block| &block.stmts)
            .filter_map(|statement| match statement {
                Statement::Assign {
                    place,
                    rvalue: Rvalue::Use(Operand::Copy(source) | Operand::Move(source)),
                    ..
                } if place.local == 0 && place.projections.is_empty() => Some(source.local),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(returned_params.len(), 2);
        let replacement = returned_params[1];
        let first_return = same_arm
            .body
            .blocks
            .iter_mut()
            .flat_map(|block| &mut block.stmts)
            .find(|statement| {
                matches!(
                    statement,
                    Statement::Assign { place, .. }
                        if place.local == 0 && place.projections.is_empty()
                )
            })
            .expect("first arm return");
        let Statement::Assign { rvalue, .. } = first_return else { unreachable!() };
        *rvalue = Rvalue::Use(Operand::Copy(Place::local(replacement)));
        assert_scalar_select_production_gate_declines("same input in both arms", &same_arm);

        let mut wrong_tag = base.clone();
        let switch = wrong_tag
            .body
            .blocks
            .iter_mut()
            .find_map(|block| match &mut block.terminator {
                Terminator::SwitchInt { targets, .. } => Some(targets),
                _ => None,
            })
            .expect("sentinel switch");
        switch[0].0 = 1;
        assert_scalar_select_production_gate_declines("wrong false-arm switch tag", &wrong_tag);

        let mut reachable_extra = base.clone();
        let extra_id = BlockId(
            reachable_extra
                .body
                .blocks
                .iter()
                .map(|block| block.id.0)
                .max()
                .expect("non-empty body")
                + 1,
        );
        let original_join = reachable_extra
            .body
            .blocks
            .iter_mut()
            .find_map(|block| match &mut block.terminator {
                Terminator::Drop { target, .. } => {
                    let original = *target;
                    *target = extra_id;
                    Some(original)
                }
                _ => None,
            })
            .expect("arm drop");
        reachable_extra.body.blocks.push(BasicBlock {
            id: extra_id,
            stmts: vec![Statement::Nop],
            terminator: Terminator::Goto(original_join),
        });
        assert_scalar_select_production_gate_declines("reachable extra block", &reachable_extra);

        let mut reassigned_param = base.clone();
        reassigned_param.body.blocks[0].stmts.push(Statement::Assign {
            place: Place::local(1),
            rvalue: Rvalue::Use(Operand::Constant(ConstValue::Int(0))),
            span: Default::default(),
        });
        assert_scalar_select_production_gate_declines("reassigned parameter", &reassigned_param);

        let mut call_dest_return = base.clone();
        let Terminator::Call { dest, .. } = &mut call_dest_return.body.blocks[0].terminator else {
            panic!("entry must be sentinel call");
        };
        *dest = Place::local(0);
        assert_scalar_select_production_gate_declines(
            "call writes return place",
            &call_dest_return,
        );

        for (label, mut flagged) in [
            ("foreign sentinel", base.clone()),
            ("unsafe sentinel", base.clone()),
            ("atomic sentinel", base.clone()),
        ] {
            let Terminator::Call { dest, atomic, is_foreign, is_unsafe_sig, .. } =
                &mut flagged.body.blocks[0].terminator
            else {
                panic!("entry must be sentinel call");
            };
            match label {
                "foreign sentinel" => *is_foreign = true,
                "unsafe sentinel" => *is_unsafe_sig = true,
                "atomic sentinel" => {
                    *atomic = Some(AtomicOperation {
                        place: Place::local(1),
                        dest: Some(dest.clone()),
                        op_kind: AtomicOpKind::Load,
                        ordering: AtomicOrdering::SeqCst,
                        failure_ordering: None,
                        span: Default::default(),
                    });
                }
                _ => unreachable!(),
            }
            assert_scalar_select_production_gate_declines(label, &flagged);
        }
    }

    #[test]
    fn assignment_typing_direct_return_lie_declines_without_safety_noise() {
        use trust_types::{BasicBlock, BlockId, ConstValue, Operand, Place, Rvalue, Statement};
        let forged = assignment_typing_function(
            "direct_bool_from_int",
            vec![trust_types::Ty::Bool],
            vec![BasicBlock {
                id: BlockId(0),
                // Overflow-free by construction: this isolates assignment typing
                // from the old F2 probe's unrelated Add-overflow obligation.
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::Use(Operand::Constant(ConstValue::Int(0))),
                    span: Default::default(),
                }],
                terminator: trust_types::Terminator::Return,
            }],
            0,
        );
        assert!(!crate::assignment_types::all_assignments_match(&forged.body));
        assert!(crate::mirsem::function_adequacy_witness(&forged).is_none());
        let safety_vcs = trust_vcgen::generate_vcs(&forged)
            .into_iter()
            .filter(|vc| crate::mirsem::is_safety_vc_kind_pub(&vc.kind))
            .collect::<Vec<_>>();
        assert!(safety_vcs.is_empty(), "the type lie must have 0/0 safety noise");
        let diagnosis = diagnose_fully_faithful_gate(&forged, &Default::default());
        assert!(!diagnosis.via_ir_shape);
        assert!(!diagnosis.via_mirsem_shape);
        assert!(!diagnosis.fully_faithful);
    }

