    /// SIGNED-MUL ADDITIVE MODEL (Lemma 5 extended to `Int.mul`). The signed-MUL
    /// overflow predicate `smul_overflows_i32 a b = (a*b < MIN ∨ a*b > MAX)` and its
    /// reflexivity adequacy lemma BOTH rest on ⊆ the 3 foundational axioms (modulo 3,
    /// no 4th axiom). The model is genuinely ADDITIVE — Add/Sub adequacy is untouched.
    #[test]
    fn signed_mul_overflow_adequacy_proven_modulo_3() {
        use crate::mirsem::{SWidth, SignedOp, check_signed_overflow_adequacy};
        for w in [SWidth::W8, SWidth::W16, SWidth::W32, SWidth::W64] {
            assert_eq!(
                check_signed_overflow_adequacy(SignedOp::Mul, w),
                crate::mirsem::AdequacyVerdict::ProvenModulo3,
                "signed-MUL overflow adequacy must be ProvenModulo3 at i{}",
                w.bits()
            );
        }
        // The additive arm did NOT regress Add/Sub adequacy.
        for op in [SignedOp::Add, SignedOp::Sub] {
            assert_eq!(
                check_signed_overflow_adequacy(op, SWidth::W32),
                crate::mirsem::AdequacyVerdict::ProvenModulo3,
            );
        }
    }

    /// THE HONEST CLASSIFICATION — the genuine-overflow controls STAY not-faithful.
    /// `mul_nonneg_pre`/`mul_nonpos_pre`/`mul_mono_pre`/`sq_nonneg` carry ONE-SIDED sign
    /// preconditions (`a>=0`, `a<=0`, `a<=b`) — NOT magnitude bounds — so their products
    /// are GENUINELY UNBOUNDED and the signed-mul overflow VC is genuinely OPEN (e.g.
    /// `sq_nonneg(46341)` wraps negative ⇒ `ret>=0` is FALSE). The emitter renders the
    /// `var*var` VC as a BITVECTOR formula, which the formula-aware faithfulness bridge
    /// DECLINES, AND the discharge gate cannot refute it. So all four STAY NOT fully
    /// faithful — modeling MUL must NOT (unsoundly) force them closed.
    #[test]
    fn signed_mul_genuine_overflow_controls_stay_not_faithful() {
        let dir =
            std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/real-spec-corpus");
        for name in ["mul_nonneg_pre", "mul_nonpos_pre", "mul_mono_pre", "sq_nonneg"] {
            let bytes = std::fs::read(dir.join(format!("{name}.json"))).expect("fixture");
            let func: VerifiableFunction = serde_json::from_slice(&bytes).expect("parse");
            // The faithfulness bridge DECLINES the BV mul VC (fail-closed, no false cert).
            assert!(
                crate::mirsem::function_safety_vcs_faithful(&func).is_none(),
                "{name}: the var*var BV signed-mul VC must DECLINE the formula-aware bridge"
            );
            // And the straight-line fully-faithful witness + discharge gate stay false.
            let ff = crate::mirsem::function_fully_faithful_witness(&func)
                .is_some_and(|c| c.is_modulo_3())
                && function_safety_vcs_all_discharged(&func);
            assert!(
                !ff,
                "{name}: a GENUINELY-OVERFLOWING signed mul (unbounded product) must STAY \
                 not-fully-faithful — forcing it would be UNSOUND"
            );
        }
    }

    /// THE NEW CAPABILITY (sound, additive) — a CONSTANT-multiplier signed mul (`x * 4`)
    /// is emitted on the LIA Int-path as `Or([Lt(Mul(x,4),MIN), Gt(Mul(x,4),MAX)])`, the
    /// SAME shape Add/Sub use, so the formula-aware bridge CERTIFIES it via the `Int.mul`
    /// spec. A `var*var` mul is emitted as a BITVECTOR formula and is DECLINED — the two
    /// cases are discriminated by the EMITTED FORMULA, never faked.
    #[test]
    fn signed_mul_lia_const_multiplier_certifies_bv_varvar_declines() {
        // const-mul (`x * 4`) → LIA shape → bridge certifies.
        assert!(
            crate::mirsem::function_safety_vcs_faithful(&synth_const_mul()).is_some(),
            "a constant-multiplier signed mul (LIA shape) must certify the faithfulness bridge"
        );
        // var*var mul (`a * b`, even bounded) → BV shape → bridge declines (fail-closed).
        assert!(
            crate::mirsem::function_safety_vcs_faithful(&synth_bounded_mul()).is_none(),
            "a var*var signed mul (BV shape) must DECLINE the faithfulness bridge"
        );
    }

    fn synth_const_mul() -> VerifiableFunction {
        use trust_types::{
            BasicBlock, BlockId, ConstValue, Formula as F, LocalDecl, Operand, Place, Rvalue, Sort,
            Statement, Terminator, Ty, VerifiableBody,
        };
        let i32_ty = Ty::Int { width: 32, signed: true };
        let body = VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: i32_ty.clone(), name: Some("_0".into()) },
                LocalDecl { index: 1, ty: i32_ty.clone(), name: Some("x".into()) },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![Statement::Assign {
                    place: Place::local(0),
                    rvalue: Rvalue::BinaryOp(
                        trust_types::BinOp::Mul,
                        Operand::Copy(Place::local(1)),
                        Operand::Constant(ConstValue::Int(4)),
                    ),
                    span: Default::default(),
                }],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: i32_ty,
        };
        VerifiableFunction {
            name: "const_mul".into(),
            def_path: "crate::const_mul".into(),
            span: Default::default(),
            body,
            contracts: vec![],
            preconditions: vec![
                F::Lt(Box::new(F::Var("x".into(), Sort::Int)), Box::new(F::Int(100))),
                F::Gt(Box::new(F::Var("x".into(), Sort::Int)), Box::new(F::Int(-100))),
            ],
            postconditions: vec![],
            spec: Default::default(),
        }
    }

