    /// PHASE 1 GATE 2 (real dump) — the §6 driver over a REAL `VerifiableFunction`
    /// dump with a struct parameter: `fn sum_bounded(p: Pt{x:i32,y:i32}) { p.x + p.y }`
    /// under field bounds. `Pt` registers as a real named inductive (modulo 3), and
    /// the add-overflow safety VC (`p.x + p.y` cannot overflow under the bounds)
    /// reconstructs to a modulo-3 kernel proof grounded STRUCTURALLY over the named
    /// inductive's projection (`structural_field_obligations` ≥ 1), 0 unsound.
    #[test]
    fn prove_struct_corpus_discharges_structurally_modulo_3() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/struct-corpus");
        if !dir.exists() {
            return; // fixture not present
        }
        let sc = prove_dump_dir(&dir).expect("read struct-corpus");
        assert_eq!(sc.kernel_rejected, 0, "0 unsound");
        assert_eq!(sc.structural_adts, 1, "Pt registers as a real named inductive modulo 3");
        assert!(
            sc.structural_field_obligations >= 1,
            "the struct-field add-overflow VC must discharge STRUCTURALLY, got {sc:?}"
        );
        assert_eq!(
            sc.opaque_struct_obligations, 0,
            "no struct-field obligation should fall back to the opaque floor here"
        );
        assert_eq!(
            sc.safety_discharged, sc.safety_obligations,
            "every safety VC reconstructs modulo 3 once field names unify"
        );
    }

    /// `fold_neg_literals` folds a negated integer LITERAL to its canonical `Int(_)`
    /// form (and leaves a NON-literal negation `Neg(Var)` untouched), recursively.
    #[test]
    fn fold_neg_literals_folds_negated_literals_only() {
        use trust_types::{Formula as F, Sort};
        // Neg(Int(2147483648)) → Int(-2147483648).
        assert_eq!(fold_neg_literals(&F::Neg(Box::new(F::Int(2147483648)))), F::Int(-2147483648));
        // A NON-literal negation is preserved (only literals fold).
        let neg_var = F::Neg(Box::new(F::Var("x".into(), Sort::Int)));
        assert_eq!(fold_neg_literals(&neg_var), neg_var);
        // Folds inside a comparison: Gt(x, Neg(Int(MIN))) → Gt(x, Int(-MIN)).
        let before = F::Gt(
            Box::new(F::Var("x".into(), Sort::Int)),
            Box::new(F::Neg(Box::new(F::Int(2147483648)))),
        );
        let after = F::Gt(Box::new(F::Var("x".into(), Sort::Int)), Box::new(F::Int(-2147483648)));
        assert_eq!(fold_neg_literals(&before), after);
    }

    /// PRECONDITION-FED DISCHARGE (Target 1 safety side): `abs_nonneg`'s
    /// `#[requires(x > i32::MIN)]` precondition, conjoined by `augment_with_type_bounds`
    /// and `Neg`-literal-folded, closes its NEGATION-overflow safety VC (`x == i32::MIN`
    /// is unreachable under `x > i32::MIN`) — the consumed `vc_refute` engine refutes the
    /// augmented formula modulo 3. Without the precondition the VC stays SMT-only.
    #[test]
    fn precondition_discharges_abs_negation_overflow_vc() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/real-spec-corpus");
        let bytes = std::fs::read(dir.join("abs_nonneg.json")).expect("abs_nonneg fixture");
        let func: VerifiableFunction = serde_json::from_slice(&bytes).expect("parse abs_nonneg");
        let carriers = crate::clean_ground::reachable_adt_carriers(&func);
        let mut adt_env = clean_kernel::Environment::with_prelude();
        let registry = crate::clean_ground::register_adt_carriers(&mut adt_env, &carriers);
        let sp = crate::vc_refute::StructParams::from_function(&func, &registry);

        let mut saw_neg = false;
        for vc in trust_vcgen::generate_vcs(&func) {
            if matches!(vc.kind, trust_types::VcKind::NegationOverflow { .. }) {
                saw_neg = true;
                // BARE (no precondition / no fold): the negation VC does NOT refute.
                assert!(
                    !matches!(
                        crate::vc_refute::check_refute_vc_with(&vc.formula, &sp),
                        Some(crate::RefuteOutcome::RefutedModulo3)
                    ),
                    "the bare negation VC must NOT refute without the precondition"
                );
                // AUGMENTED (precondition fed + Neg-literal-folded): it DOES refute.
                let aug = augment_with_type_bounds(&vc.formula, &func);
                assert_eq!(
                    crate::vc_refute::check_refute_vc_with(&aug, &sp),
                    Some(crate::RefuteOutcome::RefutedModulo3),
                    "the precondition-augmented negation VC must refute modulo 3"
                );
            }
        }
        assert!(saw_neg, "abs_nonneg must raise a NegationOverflow VC");
    }

    /// SOUNDNESS of the precondition-fed discharge: an UNGUARDED `fn neg(x: i32) { -x }`
    /// with NO precondition must NOT have its negation-overflow VC discharged — the
    /// augmentation adds no precondition fact, so `x == i32::MIN` stays reachable and the
    /// safety VC stays SMT-only (fail-closed). This proves the discharge rests on the
    /// precondition, never on the augmentation alone.
    #[test]
    fn unguarded_neg_without_precondition_stays_undischarged() {
        use trust_types::{
            BasicBlock, BlockId, LocalDecl, Operand, Place, Rvalue, Statement, Terminator, Ty,
            UnOp, VerifiableBody, VerifiableFunction,
        };
        let i = || Ty::Int { width: 32, signed: true };
        let func = VerifiableFunction {
            name: "neg".into(),
            def_path: "crate::neg".into(),
            span: Default::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: i(), name: Some("_0".into()) },
                    LocalDecl { index: 1, ty: i(), name: Some("x".into()) },
                ],
                blocks: vec![BasicBlock {
                    id: BlockId(0),
                    stmts: vec![Statement::Assign {
                        place: Place::local(0),
                        rvalue: Rvalue::UnaryOp(UnOp::Neg, Operand::Copy(Place::local(1))),
                        span: Default::default(),
                    }],
                    terminator: Terminator::Return,
                }],
                arg_count: 1,
                return_ty: i(),
            },
            contracts: vec![],
            preconditions: vec![], // NO precondition — the negation may overflow.
            postconditions: vec![],
            spec: Default::default(),
        };
        let sp = crate::vc_refute::StructParams::default();
        let mut saw_neg = false;
        for vc in trust_vcgen::generate_vcs(&func) {
            if matches!(vc.kind, trust_types::VcKind::NegationOverflow { .. }) {
                saw_neg = true;
                let aug = augment_with_type_bounds(&vc.formula, &func);
                assert!(
                    !matches!(
                        crate::vc_refute::check_refute_vc_with(&aug, &sp),
                        Some(crate::RefuteOutcome::RefutedModulo3)
                    ),
                    "an unguarded neg with NO precondition must stay UNDISCHARGED (fail-closed)"
                );
            }
        }
        assert!(saw_neg, "the unguarded neg must raise a NegationOverflow VC");
    }

    /// PHASE 2 GATE — the §6 driver over a REAL `VerifiableFunction` dump with a
    /// GENERIC struct parameter: `fn count_bump(w: Wrapper<T>{value:T, count:u32})
    /// requires w.count <= 100 { w.count + 1 }`. `Wrapper` registers as a REAL
    /// PARAMETERIZED Clean inductive (modulo 3, over `T : Type`), and the concrete
    /// `count` field's add-overflow safety VC (`count + 1` cannot overflow u32 under
    /// `count <= 100`) reconstructs to a modulo-3 kernel proof grounded STRUCTURALLY
    /// over the parameterized inductive's named `count` projection
    /// (`structural_field_obligations` >= 1), 0 unsound. The generic `value: T` field
    /// never enters the integer VCs (parametricity).
    #[test]
    fn prove_generic_struct_corpus_discharges_structurally_modulo_3() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/generic-struct-corpus");
        if !dir.exists() {
            return; // fixture not present
        }
        let sc = prove_dump_dir(&dir).expect("read generic-struct-corpus");
        assert_eq!(sc.kernel_rejected, 0, "0 unsound: {:?}", sc.rejections);
        assert_eq!(
            sc.structural_adts, 1,
            "Wrapper<T> registers as a real PARAMETERIZED inductive modulo 3, got {sc:?}"
        );
        assert!(
            sc.structural_field_obligations >= 1,
            "the concrete count-field add-overflow VC must discharge STRUCTURALLY, got {sc:?}"
        );
        assert_eq!(
            sc.opaque_struct_obligations, 0,
            "no concrete struct-field obligation should fall back to the opaque floor here"
        );
        assert_eq!(
            sc.safety_discharged, sc.safety_obligations,
            "every safety VC reconstructs modulo 3 once the count field unifies"
        );
    }

    /// PHASE 2 PARAMETRICITY — a VC that needs the GENERIC field `value: T`'s
    /// integer STRUCTURE stays UNPROVABLE (`None`, undischarged), NOT kernel-rejected
    /// and NOT falsely proven: `T` is opaque, so a fact about a `T`-typed value
    /// cannot enter the linear engine. The concrete `count` field still grounds.
    #[test]
    fn generic_field_t_structure_stays_unprovable_parametricity() {
        use trust_types::{Formula as F, LocalDecl, Sort, Ty, VerifiableBody, VerifiableFunction};
        let ty = Ty::Adt { adt_kind: None, layout: None, 
            variants: Vec::new(),
            name: "Wrapper".into(),
            fields: vec![
                (
                    "value".into(),
                    Ty::Unsupported {
                        kind: "TyKind::Param".into(),
                        detail: "generic parameter T/#0 needs monomorphization".into(),
                    },
                ),
                ("count".into(), Ty::Int { width: 32, signed: false }),
            ],
            disc_index_safe: false,
            faithful_enum_repr: None, enum_layout: None, };
        let carrier =
            crate::reflect::reflect_struct(&ty).expect("Wrapper<T> reflects parameterized");
        let mut env = clean_kernel::Environment::with_prelude();
        let registry =
            crate::clean_ground::register_adt_carriers(&mut env, std::slice::from_ref(&carrier));
        assert_eq!(registry.len(), 1, "Wrapper<T> registers parameterized modulo 3");

        let u32t = || Ty::Int { width: 32, signed: false };
        let func = VerifiableFunction {
            name: "uses_wrapper".into(),
            def_path: "crate::uses_wrapper".into(),
            span: Default::default(),
            body: VerifiableBody {
                locals: vec![
                    LocalDecl { index: 0, ty: u32t(), name: Some("_0".into()) },
                    LocalDecl { index: 1, ty, name: Some("w".into()) },
                ],
                blocks: vec![],
                arg_count: 1,
                return_ty: u32t(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
        };
        let params = crate::vc_refute::StructParams::from_function(&func, &registry);

        // The concrete `count` field IS a structural Int field — it grounds over the
        // parameterized inductive's named `count` projection (an Int operand).
        assert!(params.is_struct_int_field("w.count"), "count is a structural Int field");
        // … but the generic `value: T` field is NOT an integer operand. `T` is opaque
        // (no axiom about its structure), so a fact requiring `w.value`'s STRUCTURE
        // can never enter the linear engine via the structural-field path. This is
        // the parametricity fail-closed: sound (never falsely proven), and crucially
        // NOT a kernel rejection — the field is simply outside the integer fragment.
        assert!(
            !params.is_struct_int_field("w.value"),
            "the generic T field must NOT be a structural Int field (parametricity)"
        );
        // The depth metric must classify a `w.count` VC as STRUCTURAL (it grounds over
        // the named `count` projection of the registered parameterized inductive,
        // kernel-certified modulo 3), while a `w.value`-only VC is NOT a struct-field
        // obligation at all (`None`): the generic `T` field never grounds over a
        // registered Int projection (parametricity fail-closed).
        let count_vc = F::Le(Box::new(F::Var("w.count".into(), Sort::Int)), Box::new(F::Int(100)));
        let value_vc = F::Le(Box::new(F::Var("w.value".into(), Sort::Int)), Box::new(F::Int(100)));
        assert_eq!(
            classify_struct_field_grounding(&count_vc, &params, &env),
            StructFieldGrounding::Structural,
            "a VC over the concrete count field grounds structurally over the named projection"
        );
        assert_eq!(
            classify_struct_field_grounding(&value_vc, &params, &env),
            StructFieldGrounding::None,
            "a VC over the generic T field never grounds structurally (parametricity fail-closed)"
        );
    }

    /// GOAL-ITEM #1 (real-corpus shape) — a struct-field safety obligation that is
    /// GENUINELY UNDISCHARGEABLE (the unsigned `p.x + p.y` overflow VC stays SAT with
    /// NO bounding precondition — exactly the real `pt_sum`) STILL grounds STRUCTURALLY
    /// over the named `Trust.Adt.Point.x`/`.y` projections: the field references resolve
    /// to the registered named inductive's kernel-certified projections regardless of
    /// whether the overflow VC refutes. This is the decoupling the real corpus needs —
    /// the structural grounding is honest (the field projects the named inductive) even
    /// though the obligation is correctly NOT counted as discharged. Crucially: the VC
    /// does NOT refute, so this is no false proof.
    #[test]
    fn undischargeable_struct_field_vc_still_grounds_structurally() {
        use trust_types::{Formula as F, Sort, Ty};
        let ty = Ty::Adt { adt_kind: None, layout: None, 
            variants: Vec::new(),
            name: "Point".into(),
            fields: vec![
                ("x".into(), Ty::Int { width: 32, signed: false }),
                ("y".into(), Ty::Int { width: 32, signed: false }),
            ],
            disc_index_safe: false,
            faithful_enum_repr: None, enum_layout: None, };
        let carrier = crate::reflect::reflect_struct(&ty).expect("Point reflects");
        let mut env = clean_kernel::Environment::with_prelude();
        let registry =
            crate::clean_ground::register_adt_carriers(&mut env, std::slice::from_ref(&carrier));
        assert_eq!(registry.len(), 1, "Point registers as a real inductive modulo 3");

        let u32t = || Ty::Int { width: 32, signed: false };
        let func = VerifiableFunction {
            name: "pt_sum".into(),
            def_path: "crate::pt_sum".into(),
            span: Default::default(),
            body: trust_types::VerifiableBody {
                locals: vec![
                    trust_types::LocalDecl { index: 0, ty: u32t(), name: Some("_0".into()) },
                    trust_types::LocalDecl { index: 1, ty, name: Some("p".into()) },
                ],
                blocks: vec![],
                arg_count: 1,
                return_ty: u32t(),
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
        };
        let params = crate::vc_refute::StructParams::from_function(&func, &registry);

        // The UNBOUNDED `p.x + p.y` overflow obligation (u32 range + the overflow arm)
        // is genuinely SAT (e.g. p.x = p.y = 2^32-1) — it must NOT refute.
        let fx = || F::Var("p.x".into(), Sort::Int);
        let fy = || F::Var("p.y".into(), Sort::Int);
        let vc = F::And(vec![
            F::Ge(Box::new(fx()), Box::new(F::Int(0))),
            F::Le(Box::new(fx()), Box::new(F::Int(4294967295))),
            F::Ge(Box::new(fy()), Box::new(F::Int(0))),
            F::Le(Box::new(fy()), Box::new(F::Int(4294967295))),
            F::Gt(Box::new(F::Add(Box::new(fx()), Box::new(fy()))), Box::new(F::Int(4294967295))),
        ]);
        assert_eq!(
            crate::vc_refute::check_refute_vc_with(&vc, &params),
            None,
            "a genuinely-overflowing struct-field VC must NOT refute (no false proof)"
        );
        // … yet it grounds STRUCTURALLY: p.x and p.y both project the named inductive.
        assert_eq!(
            classify_struct_field_grounding(&vc, &params, &env),
            StructFieldGrounding::Structural,
            "the field references ground over the named projection even when undischarged"
        );
    }

    /// PHASE 1 DEPTH METRIC — a struct-field safety VC discharges STRUCTURALLY.
    /// A function `fn(p: Pt{x:i32,y:i32})` whose `p.x + p.y` overflow VC is bounded
    /// (`0≤p.x≤5 ∧ 0≤p.y≤3`) reconstructs modulo 3 AND is counted as a structural
    /// (named-projection) obligation, not an opaque one — proving the depth metric
    /// reads structural for a real registered struct.
    #[test]
    fn struct_field_vc_counts_as_structural_grounding() {
        use trust_types::{Formula as F, Sort, Ty};
        // Register Pt{x:i32,y:i32}.
        let ty = Ty::Adt { adt_kind: None, layout: None, 
            variants: Vec::new(),
            name: "Pt".into(),
            fields: vec![
                ("x".into(), Ty::Int { width: 32, signed: true }),
                ("y".into(), Ty::Int { width: 32, signed: true }),
            ],
            disc_index_safe: false,
            faithful_enum_repr: None, enum_layout: None, };
        let carrier = crate::reflect::reflect_struct(&ty).expect("Pt reflects");
        let mut env = clean_kernel::Environment::with_prelude();
        let registry =
            crate::clean_ground::register_adt_carriers(&mut env, std::slice::from_ref(&carrier));
        assert_eq!(registry.len(), 1, "Pt must register as a real inductive modulo 3");

        // Build StructParams from a function with param `p : Pt`.
        let func = VerifiableFunction {
            name: "sum_bounded".into(),
            def_path: "crate::sum_bounded".into(),
            span: Default::default(),
            body: trust_types::VerifiableBody {
                locals: vec![
                    trust_types::LocalDecl {
                        index: 0,
                        ty: Ty::Int { width: 32, signed: true },
                        name: Some("_0".into()),
                    },
                    trust_types::LocalDecl { index: 1, ty, name: Some("p".into()) },
                ],
                blocks: vec![],
                arg_count: 1,
                return_ty: Ty::Int { width: 32, signed: true },
            },
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: Default::default(),
        };
        let params = crate::vc_refute::StructParams::from_function(&func, &registry);

        // The bounded `p.x + p.y > 1000` VC reconstructs modulo 3 …
        let fx = || F::Var("p.x".into(), Sort::Int);
        let fy = || F::Var("p.y".into(), Sort::Int);
        let vc = F::And(vec![
            F::Ge(Box::new(fx()), Box::new(F::Int(0))),
            F::Le(Box::new(fx()), Box::new(F::Int(5))),
            F::Ge(Box::new(fy()), Box::new(F::Int(0))),
            F::Le(Box::new(fy()), Box::new(F::Int(3))),
            F::Gt(Box::new(F::Add(Box::new(fx()), Box::new(fy()))), Box::new(F::Int(1000))),
        ]);
        assert_eq!(
            crate::vc_refute::check_refute_vc_with(&vc, &params),
            Some(crate::RefuteOutcome::RefutedModulo3),
        );
        // … AND the depth metric classifies it as a STRUCTURAL obligation: its p.x/p.y
        // references both ground over the named `Trust.Adt.Pt.x`/`.y` projections,
        // kernel-certified modulo 3.
        assert_eq!(
            classify_struct_field_grounding(&vc, &params, &env),
            StructFieldGrounding::Structural,
            "a VC over registered struct fields p.x/p.y must count as structural grounding"
        );
        // A non-struct VC is NOT a struct-field obligation at all.
        let plain = F::Lt(Box::new(F::Var("z".into(), Sort::Int)), Box::new(F::Int(0)));
        assert_eq!(
            classify_struct_field_grounding(&plain, &params, &env),
            StructFieldGrounding::None,
        );
    }

    /// The §6 driver over the checked-in REAL MIR-extracted fixtures must be
