    // =======================================================================
    // Trust: M6 rung 11 — LITERAL-CONDITION ASSERT-GUARD ADMISSION. Rung 10's own
    // confirmation pass (`reports/m6-rung10-confirmation-2026-07-10.md` §6) found
    // that `bit_test_chain_function` above (Goto/Return only, no `Assert` block) is
    // NOT the real MIR shape: the genuine `has_fvar`/`has_level_param` dump is a
    // 2-block, `Terminator::Assert`-GATED chain (`trustc`'s shift-overflow guard):
    // `bb0: _4 := (*self).0; _5 := Lt(Const(k), Const(W)); Assert(_5, expected=true,
    // Overflow(Shr)) -> bb1`; `bb1: _3 := Shr(_4,k); _2 := BitAnd(_3,1); _0 :=
    // Eq(_2,1); Return`. This fixture reproduces THAT shape byte-for-byte
    // (structurally), not the rung-9 hand-simplification.
    // =======================================================================

    /// The REAL `ExprMeta::{has_fvar,has_level_param}` 2-block shape: an entry
    /// block that reads `self.0` then computes the shift-amount-in-range guard
    /// `_5 := Lt(<guard lhs>, Const(width_threshold))` and `Assert`s it
    /// (`expected: true`) before falling through to the bit-test chain.
    /// `guard_lhs_literal` selects the guard's LEFT operand: a literal `Const(k)`
    /// (the genuine, always-closed shape trustc emits for a `x >> <const>` shift)
    /// when `true`, or the field-read temp `Move(_4)` (a NON-literal, run-time-
    /// dependent guard — never trustc's own output for a literal shift amount, but
    /// the shape any OTHER (non-constant-amount) checked op would produce) when
    /// `false`.
    fn bit_test_chain_function_assert_gated(
        k: u128,
        width_threshold: u128,
        field_signed: bool,
        guard_lhs_literal: bool,
    ) -> VerifiableFunction {
        use trust_types::{
            BasicBlock, BinOp, BlockId, ConstValue, FunctionSpec, LocalDecl, Operand, Place,
            Projection, Rvalue, SourceSpan, Statement, Terminator, Ty, VerifiableBody,
        };
        let field_ty = Ty::Int { width: 64, signed: field_signed };
        let meta_ty = Ty::adt("probe::Meta", vec![("0".into(), field_ty.clone())]);
        let assign = |local: usize, rvalue: Rvalue| Statement::Assign {
            place: Place { local, projections: vec![] },
            rvalue,
            span: SourceSpan::default(),
        };
        let guard_lhs = if guard_lhs_literal {
            Operand::Constant(ConstValue::Uint(k, 32))
        } else {
            Operand::Move(Place { local: 4, projections: vec![] })
        };
        let body = VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: Ty::Bool, name: None },
                LocalDecl { index: 1, ty: meta_ty, name: Some("self".into()) },
                LocalDecl { index: 2, ty: field_ty.clone(), name: None },
                LocalDecl { index: 3, ty: field_ty.clone(), name: None },
                LocalDecl { index: 4, ty: field_ty, name: None },
                LocalDecl { index: 5, ty: Ty::Bool, name: None },
            ],
            blocks: vec![
                BasicBlock {
                    id: BlockId(0),
                    stmts: vec![
                        // _4 := Use(Copy(self.0))
                        assign(
                            4,
                            Rvalue::Use(Operand::Copy(Place {
                                local: 1,
                                projections: vec![Projection::Field(0)],
                            })),
                        ),
                        // _5 := Lt(<guard_lhs>, Const(width_threshold))
                        assign(
                            5,
                            Rvalue::BinaryOp(
                                BinOp::Lt,
                                guard_lhs,
                                Operand::Constant(ConstValue::Uint(width_threshold, 32)),
                            ),
                        ),
                    ],
                    terminator: Terminator::Assert {
                        unwind: UnwindEdge::Unreachable,
                        cond: Operand::Move(Place { local: 5, projections: vec![] }),
                        expected: true,
                        msg: trust_types::AssertMessage::Overflow(BinOp::Shr),
                        target: BlockId(1),
                        span: SourceSpan::default(),
                    },
                },
                BasicBlock {
                    id: BlockId(1),
                    stmts: vec![
                        // _3 := Shr(Move(_4), k)
                        assign(
                            3,
                            Rvalue::BinaryOp(
                                BinOp::Shr,
                                Operand::Move(Place { local: 4, projections: vec![] }),
                                Operand::Constant(ConstValue::Uint(k, 32)),
                            ),
                        ),
                        // _2 := BitAnd(Move(_3), 1)
                        assign(
                            2,
                            Rvalue::BinaryOp(
                                BinOp::BitAnd,
                                Operand::Move(Place { local: 3, projections: vec![] }),
                                Operand::Constant(ConstValue::Uint(1, 64)),
                            ),
                        ),
                        // _0 := Eq(Move(_2), 1)
                        assign(
                            0,
                            Rvalue::BinaryOp(
                                BinOp::Eq,
                                Operand::Move(Place { local: 2, projections: vec![] }),
                                Operand::Constant(ConstValue::Uint(1, 64)),
                            ),
                        ),
                    ],
                    terminator: Terminator::Return,
                },
            ],
            arg_count: 1,
            return_ty: Ty::Bool,
        };
        VerifiableFunction {
            name: "bit_test_chain_assert_gated".into(),
            def_path: "bit_test_chain_assert_gated".into(),
            span: SourceSpan::default(),
            body,
            contracts: vec![],
            preconditions: vec![],
            postconditions: vec![],
            spec: FunctionSpec::default(),
        }
    }

    /// POSITIVE — THE MISSION'S TARGET SHAPE, THIS TIME FOR REAL: the genuine
    /// `has_fvar`/`has_level_param` 2-block, `Assert`-GATED chain (in-range literal
    /// shift amount, `k=40 < W=64`) now certifies via
    /// [`straight_line_chain_fully_faithful_via_trustir`] AND the full production
    /// gate — closing rung 10's own confirmed REFUTATION (the rung-9 fixture never
