    /// CLAUSE-LEVEL PIN (M1 either landing) — the REAL `either::is_right` dump
    /// composes over the REAL certified `is_left` through EVERY clause of both
    /// fully-faithful lanes. This is the root-cause regression pin for the
    /// synthesized-tag-fact registry bug: the real `is_left` dump carries the
    /// extractor's ALWAYS-TRUE `_2 ∈ {0,1}` enum-tag fact in `preconditions`
    /// while declaring 0 requires; `of_certified` used to count it against the
    /// declared-completeness gate ⇒ `requires: None` ⇒ every call site failed
    /// closed — clause-by-clause diagnosis showed EVERY other clause green and
    /// exactly `function_call_requires_established == false` on both lanes.
    #[test]
    fn either_is_right_composes_over_certified_is_left_clause_pins() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/either-discriminant-corpus");
        let load = |n: &str| -> VerifiableFunction {
            serde_json::from_slice(&std::fs::read(dir.join(n)).expect("read fixture"))
                .expect("parse fixture")
        };
        let is_left = load("Either__<L, R>__is_left.json");
        let is_right = load("Either__<L, R>__is_right.json");
        let mut registry = std::collections::BTreeMap::new();
        registry
            .insert(is_left.def_path.clone(), crate::mirsem::CalleeFact::of_certified(&is_left));
        // THE ROOT-CAUSE PIN: the tag fact partitions out; the callee's declared
        // requires set is KNOWN-EMPTY (`Some([])`), never UNKNOWN (`None`).
        assert_eq!(
            registry[&is_left.def_path].requires,
            Some(vec![]),
            "of_certified must partition the synthesized `_2 ∈ {{0,1}}` tag fact out of \
             the caller-facing requires — None here re-opens the registry bug"
        );
        // MirSem lane, clause by clause.
        let shape = crate::mirsem::sem_call_then_pureop_of_mir(&is_right, &registry)
            .expect("the real is_right recognizes as Call-then-Not over certified is_left");
        assert_eq!(shape.call.callee, is_left.def_path);
        assert!(shape.call_is_lhs);
        assert_eq!(shape.other, crate::mirsem::SemOperand::Const(0));
        assert!(
            crate::mirsem::call_then_pureop_adequacy_witness(&shape).is_some(),
            "the MirSem Call-then-Not certificate must mint for the real dump"
        );
        assert!(
            crate::mirsem::function_fully_faithful_witness_with_callees(&is_right, &registry)
                .is_some_and(|c| c.is_modulo_3()),
            "the composed MirSem witness must mint modulo 3"
        );
        assert!(!crate::mirsem::function_emits_unmodeled_safety_vc_pub(&is_right));
        assert!(function_safety_vcs_all_discharged(&is_right));
        assert!(
            function_call_requires_established(&is_right, &registry),
            "requires establishment must be VACUOUS for a known-empty requires set \
             (this exact clause was the pre-fix decline on both lanes)"
        );
        // trust-ir lane: the full predicate (all four clauses conjoined).
        assert!(
            call_then_pureop_fully_faithful_via_trustir(&is_right, &registry),
            "the real is_right must certify on the trust-ir call-then-pureop lane"
        );
    }

    /// INCREMENT A — the pointer-offset-as-`Call` counter recognizer fires on the REAL
    /// `count_raw` MIR: the back-edge block (`bb7`: `_5 := Move(_15)`) commits the
    /// pointer-walk `ptr = ptr.offset(1)`, whose `_15` is the DEST of the
    /// `core::ptr::const_ptr::<impl *const T>::offset` `Call` in `bb6` — previously
    /// INVISIBLE to `resolve_counter_update` (Case A/B only see `Statement::Assign`
    /// forms). `extract_loop_shape` now recognizes the WHOLE loop shape (guard `ptr <
    /// end` + counter update `ptr := ptr + 1`).
    #[test]
    fn count_raw_ptr_offset_call_counter_recognized() {
        let func = load_count_raw_fixture();
        let (cond, counter_idx, sem_rv) =
            extract_loop_shape(&func).expect("count_raw's ptr<end loop must extract a shape");
        // ptr is MIR local 5 (env index 5); end is the parameter `end` (MIR local 3, env
        // index 2 — `end` is the SECOND parameter after `self`/`start`).
        assert_eq!(counter_idx, 5, "the counter is `ptr` (MIR local 5)");
        assert!(
            matches!(cond.op, crate::mirsem::SemCmpOp::Lt),
            "the guard is `ptr < end`, got {:?}",
            cond.op
        );
        assert_eq!(cond.a, crate::mirsem::SemOperand::Var(5), "guard LHS is `ptr`");
        assert_eq!(cond.b, crate::mirsem::SemOperand::Var(2), "guard RHS is `end`");
        assert_eq!(
            sem_rv,
            crate::mirsem::SemRvalue::Bin(
                crate::mirsem::SemBinOp::Add,
                crate::mirsem::SemOperand::Var(5),
                crate::mirsem::SemOperand::Const(1),
            ),
            "the recovered counter update must be `ptr := ptr + 1` (Increment A), got {:?}",
            sem_rv
        );
    }

    #[test]
