    /// FAIL-CLOSED, end to end: the Lowerer-class body (an `Assert` spliced
    /// onto the then path — the `debug_assert!` + checked-`Sub` blocker) must
    /// NOT certify on the new lane OR the top-level gate: its panic arm is
    /// reachable without the caller's precondition, so a `Some/None` totality
    /// claim would be false.
    #[test]
    fn adt_return_opaque_lane_declines_assert_gated_body() {
        use trust_types::{AssertMessage, Operand, Terminator};
        let mut func = crate::mirsem::opaque_fixtures::lifter_fold_bvar_opt_func();
        let Terminator::Call { target, .. } = &mut func.body.blocks[1].terminator else {
            panic!("bb1 must be the checked_add_u32 call");
        };
        *target = Some(trust_types::BlockId(6));
        func.body.blocks.push(trust_types::BasicBlock {
            id: trust_types::BlockId(6),
            stmts: vec![],
            terminator: Terminator::Assert {
                unwind: UnwindEdge::Unreachable,
                cond: Operand::Copy(trust_types::Place::local(3)),
                expected: true,
                msg: AssertMessage::Overflow(trust_types::BinOp::Sub),
                target: trust_types::BlockId(2),
                span: Default::default(),
            },
        });
        assert!(
            !adt_return_opaque_fully_faithful_via_trustir(&func),
            "an Assert-gated arm path must not certify on the opaque-chain lane"
        );
    }

