    #[test]
    fn instantiator_ordering_leaf_exact_vc_hash_and_discharge() {
        let func = load_instantiator_ordering_leaf();
        assert_eq!(
            func.content_hash(),
            crate::mirsem::INSTANTIATOR_ORD_LEAF_CONTENT_HASH,
            "audited body hash drift"
        );
        assert!(crate::mirsem::sem_adt_return_opaque_ord_shape_of(&func).is_some());
        let safety_vcs = trust_vcgen::generate_vcs(&func)
            .into_iter()
            .filter(|vc| crate::mirsem::is_safety_vc_kind_pub(&vc.kind))
            .collect::<Vec<_>>();
        let [vc] = safety_vcs.as_slice() else {
            panic!("exactly one safety VC, got {}", safety_vcs.len());
        };
        assert_eq!(
            vc_kind_formula_hash(vc).as_deref(),
            Some(INSTANTIATOR_ORD_LEAF_VC_HASH),
            "pinned (VcKind, Formula) digest drift"
        );
        assert_eq!(exact_instantiator_ord_safety_discharge(&func, &safety_vcs), Some(true));
        assert!(adt_return_opaque_ord_fully_faithful_via_trustir(&func));
    }

    #[test]
    fn instantiator_ordering_fact_cannot_attach_to_wrong_or_later_vc() {
        use trust_types::{BinOp, Formula, Ty, VcKind};

        let func = load_instantiator_ordering_leaf();
        let safety_vcs = trust_vcgen::generate_vcs(&func)
            .into_iter()
            .filter(|vc| crate::mirsem::is_safety_vc_kind_pub(&vc.kind))
            .collect::<Vec<_>>();
        let [honest] = safety_vcs.as_slice() else {
            panic!("exactly one safety VC, got {}", safety_vcs.len());
        };

        let mut wrong_kind = honest.clone();
        wrong_kind.kind = VcKind::ArithmeticOverflow {
            op: BinOp::Add,
            operand_tys: (
                Ty::Int { width: 32, signed: false },
                Ty::Int { width: 32, signed: false },
            ),
        };
        assert_eq!(
            exact_instantiator_ord_safety_discharge(&func, &[wrong_kind]),
            Some(false),
            "a different arithmetic VC must not inherit the comparison fact"
        );

        let mut wrong_formula = honest.clone();
        wrong_formula.formula = Formula::Bool(true);
        assert_eq!(
            exact_instantiator_ord_safety_discharge(&func, &[wrong_formula]),
            Some(false),
            "formula/hash drift must fail closed even when the owner is exact"
        );

        let mut later_vc = safety_vcs.clone();
        later_vc.push(honest.clone());
        assert_eq!(
            exact_instantiator_ord_safety_discharge(&func, &later_vc),
            Some(false),
            "an arbitrary later safety VC must invalidate the exact one-VC lane"
        );
    }

    /// Load one exact monomorphized Option/Result payload-accessor body by
    /// `def_path` from the committed corpus.
    fn load_optres_payload_dump(def_path: &str) -> VerifiableFunction {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("fixtures/optres-payload-extract-2026-07-17/dumps");
        std::fs::read_dir(&dir)
            .unwrap_or_else(|error| panic!("read {}: {error}", dir.display()))
            .map(|entry| entry.expect("read payload corpus entry").path())
            .filter(|path| path.extension().and_then(|ext| ext.to_str()) == Some("json"))
            .find_map(|path| {
                let bytes = std::fs::read(&path)
                    .unwrap_or_else(|error| panic!("read {}: {error}", path.display()));
                let function: VerifiableFunction = serde_json::from_slice(&bytes)
                    .unwrap_or_else(|error| panic!("decode {}: {error}", path.display()));
                (function.def_path == def_path).then_some(function)
            })
            .unwrap_or_else(|| panic!("{def_path} missing from {}", dir.display()))
    }

    /// Assert the deliberately retained recognizer/kernel diagnostic still has
    /// teeth while the production fully-faithful gate refuses the panicking body.
    fn assert_panicking_payload_extract_is_not_production_authority(func: &VerifiableFunction) {
        assert!(
            crate::mirsem::sem_adt_payload_extract_diverging_of_discriminant_switch(func).is_some(),
            "{}: load-bearing control: the diagnostic shape must recognize",
            func.def_path
        );
        assert!(
            optres_payload_extract_diverging_diagnostic_via_trustir(func),
            "{}: the non-panicking payload/kernel diagnostic must remain exercisable",
            func.def_path
        );
        assert!(
            !function_fully_faithful_via_trustir(func),
            "{}: a reachable unwrap/expect panic must never enter TrustIR production authority",
            func.def_path
        );
        let diagnosis = diagnose_fully_faithful_gate(func, &Default::default());
        assert!(
            !diagnosis.via_ir_shape,
            "{}: the quarantined diagnostic must be absent from the production shape disjunction",
            func.def_path
        );
        assert!(
            !diagnosis.fully_faithful,
            "{}: treating panic as ordinary divergence would certify a partial function",
            func.def_path
        );
    }

    #[test]
    fn option_unwrap_panic_is_quarantined_at_production_gate() {
        let func = load_optres_payload_dump("std::option::Option::<i32>::unwrap");
        assert_panicking_payload_extract_is_not_production_authority(&func);
    }

    #[test]
    fn option_expect_panic_is_quarantined_at_production_gate() {
        let func = load_optres_payload_dump("std::option::Option::<i32>::expect");
        assert_panicking_payload_extract_is_not_production_authority(&func);
    }

    #[test]
    fn result_unwrap_panic_is_quarantined_at_production_gate() {
        let func = load_optres_payload_dump("std::result::Result::<i32, u8>::unwrap");
        assert_panicking_payload_extract_is_not_production_authority(&func);
    }

    #[test]
    fn result_expect_panic_is_quarantined_at_production_gate() {
        use trust_types::{BlockId, Operand, Projection, Rvalue, Statement, Terminator};

        // The checked-in corpus has Option::expect and Result::unwrap but no
        // monomorphized Result::expect body. Build the exact two-parameter Result
        // tag/payload dual from those two real extracts: retain Option::expect's
        // `(self, msg)` ABI/CFG, replace `self` with the real Result<i32,u8> type,
        // route Ok(0) to the return arm and Err(1) to the panic arm, and bind the
        // payload read to Downcast(Ok). Production authority is shape-based, so
        // this also pins that a callable name cannot bypass the quarantine.
        let mut func = load_optres_payload_dump("std::option::Option::<i32>::expect");
        let result_unwrap = load_optres_payload_dump("std::result::Result::<i32, u8>::unwrap");
        func.name = "expect".to_string();
        func.def_path = "std::result::Result::<i32, u8>::expect".to_string();
        func.body.locals[1].ty = result_unwrap.body.locals[1].ty.clone();

        let entry =
            func.body.blocks.iter_mut().find(|block| block.id == BlockId(0)).expect("expect entry");
        let Terminator::SwitchInt { targets, .. } = &mut entry.terminator else {
            panic!("expect entry is a discriminant switch");
        };
        for (tag, target) in targets {
            *target = match *tag {
                0 => BlockId(3), // Ok: return payload
                1 => BlockId(2), // Err: panic
                other => panic!("unexpected Result tag {other}"),
            };
        }

        let happy = func
            .body
            .blocks
            .iter_mut()
            .find(|block| block.id == BlockId(3))
            .expect("expect happy arm");
        let Statement::Assign {
            rvalue: Rvalue::Use(Operand::Copy(place) | Operand::Move(place)),
            ..
        } = &mut happy.stmts[0]
        else {
            panic!("expect happy arm reads the payload");
        };
        let Some(Projection::Downcast(variant)) = place.projections.first_mut() else {
            panic!("expect payload read starts with Downcast");
        };
        *variant = 0; // Ok

        let panic_arm = func
            .body
            .blocks
            .iter_mut()
            .find(|block| block.id == BlockId(2))
            .expect("expect panic arm");
        let Terminator::Opaque { kind, .. } = &mut panic_arm.terminator else {
            panic!("expect failure is opaque panic MIR");
        };
        *kind = "Call::std::result::unwrap_failed::UnsupportedUnwind(Continue)".to_string();

        assert_panicking_payload_extract_is_not_production_authority(&func);
    }

    #[test]
    fn nonpanicking_unwrap_or_payload_extract_remains_production_authority() {
        for def_path in
            ["std::option::Option::<i32>::unwrap_or", "std::result::Result::<i32, u8>::unwrap_or"]
        {
            let func = load_optres_payload_dump(def_path);
            assert!(
                crate::mirsem::sem_adt_payload_extract_of_discriminant_switch(&func).is_some(),
                "{def_path}: the two-value-arm payload/default shape remains recognized"
            );
            assert!(
                crate::mirsem::sem_adt_payload_extract_diverging_of_discriminant_switch(&func)
                    .is_none(),
                "{def_path}: a returning default arm is not a panic/divergence shape"
            );
            assert!(
                function_fully_faithful_via_trustir(&func),
                "{def_path}: quarantining reachable panic must not regress the total unwrap_or lane"
            );
            assert!(
                diagnose_fully_faithful_gate(&func, &Default::default()).fully_faithful,
                "{def_path}: the non-panicking paired lane must stay production-authoritative"
            );
        }
    }

    /// Trust: GAP-CROSS-SIGN-WIDEN (2026-07-16) — the TRUST-IR-ANCHOR lane sibling
    /// of `mirsem::resolve_widening_cast_rvalue_signcross_widen_admits_and_fail_closed`.
    /// `ir_resolve_widening_cast_rvalue` must admit a sign-crossing WIDENING
    /// `u_w -> i_W` (`W > w`) as the identity `Use`, and DECLINE every near-miss:
    /// same-width sign cross, narrowing sign cross, and `i -> u` wrong-way cross.
    #[test]
    fn ir_resolve_widening_cast_signcross_widen_admits_and_fail_closed() {
        use trust_types::{
            BasicBlock, BlockId, LocalDecl, Operand, Place, Terminator, Ty, VerifiableBody,
        };

        use crate::trustir_anchor::{IrOperand, IrRvalue};
        let int = |w: u32, s: bool| Ty::Int { width: w, signed: s };
        let mk = |src: Ty, ret: Ty| VerifiableBody {
            locals: vec![
                LocalDecl { index: 0, ty: ret.clone(), name: None },
                LocalDecl { index: 1, ty: src, name: Some("src".into()) },
            ],
            blocks: vec![BasicBlock {
                id: BlockId(0),
                stmts: vec![],
                terminator: Terminator::Return,
            }],
            arg_count: 1,
            return_ty: ret,
        };
        let param_index = |local: usize| -> Option<u64> { (local == 1).then_some(0) };
        // A minimal operand lowering: the sole parameter (local 1) is `Var 0`.
        let to_ir: &dyn Fn(&Operand) -> Option<IrOperand> = &|op: &Operand| match op {
            Operand::Copy(p) | Operand::Move(p) if p.local == 1 && p.projections.is_empty() => {
                Some(IrOperand::Var(0))
            }
            _ => None,
        };
        let op = Operand::Copy(Place::local(1));

        // POSITIVE: the real sign-crossing widenings admit as `Use(Var 0)`.
        for (sw, dw) in [
            (8u32, 16u32),
            (8, 32),
            (8, 64),
            (8, 128),
            (16, 32),
            (16, 64),
            (16, 128),
            (32, 64),
            (32, 128),
            (64, 128),
        ] {
            let body = mk(int(sw, false), int(dw, true));
            assert_eq!(
                ir_resolve_widening_cast_rvalue(
                    &body,
                    &op,
                    &int(dw, true),
                    to_ir,
                    &param_index,
                    BlockId(0),
                    None,
                ),
                Some(IrRvalue::Use(IrOperand::Var(0))),
                "trust-ir lane: u{sw} -> i{dw} (W>w) must admit as value-identity"
            );
        }
        // NAMED DECLINE: same-width sign cross, narrowing sign cross, i->u wrong way.
        for (src, dst) in [
            (int(8, false), int(8, true)), // same-width sign cross
            (int(16, false), int(16, true)),
            (int(16, false), int(8, true)), // narrowing sign cross
            (int(64, false), int(32, true)),
            (int(8, true), int(16, false)), // i -> u wrong way (widening)
            (int(8, true), int(64, false)),
            (int(64, true), int(16, true)), // signed narrowing
        ] {
            let body = mk(src.clone(), dst.clone());
            assert_eq!(
                ir_resolve_widening_cast_rvalue(
                    &body,
                    &op,
                    &dst,
                    to_ir,
                    &param_index,
                    BlockId(0),
                    None,
                ),
                None,
                "trust-ir lane: {src:?} -> {dst:?} must decline (fail-closed near-miss)"
            );
        }
    }

    // ================================================================================
    // W2 INCREMENT-1 — SLICE-INDEX-LOOP PARTIAL-TIER LANE tests. The genuinely-inductive
    // unbounded-loop certificate over real slice code (`while_idx`), its three mandatory
    // adversarial gates, and the forgery probes. See the mirsem module comment for the
    // full design + gate rationale.
    // ================================================================================

    /// Load the function named `def_path` from the w2-iter-harvest dumps directory, or
    /// `None` if the fixture isn't present in this checkout.
    fn w2_function(def_path: &str) -> Option<VerifiableFunction> {
        let dir =
            Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures/w2-iter-harvest-2026-07-20/dumps");
        if !dir.exists() {
            return None;
        }
        for entry in std::fs::read_dir(&dir).ok()?.flatten() {
            let path = entry.path();
            if path.extension().and_then(|e| e.to_str()) != Some("json") {
                continue;
            }
            let Ok(bytes) = std::fs::read(&path) else { continue };
            if let Ok(f) = decode_verifiable_function_with_authenticated_legacy_metadata(&bytes) {
                if f.def_path == def_path {
                    return Some(f);
                }
            }
        }
        None
    }

    /// HEADLINE — the first unbounded-loop certificate over real slice code. `while_idx`
    /// is recognized and its PARTIAL-tier obligations (invariant + BoundsCheck-assert
    /// discharge + counter-increment-overflow discharge) ALL kernel-check modulo 3;
    /// termination is NOT claimed (a panic exit remains), and the function's overall
    /// verdict is UNCHANGED (this lane never flips it to fully-faithful).
    #[test]
    fn w2_while_idx_partial_tier_certificate_kernel_checks() {
        use crate::mirsem::RefinementVerdict::ProvenModulo3;
        let Some(func) = w2_function("while_idx") else {
            eprintln!("w2 fixture absent — skipping");
            return;
        };
        // The recognizer accepts the exact fragment.
        let silf = extract_slice_index_loop_function(&func)
            .expect("while_idx is the recognized slice-index-loop fragment");
        assert_eq!(silf.counter_width, 64, "the usize counter is 64-bit");
        assert_eq!(silf.guard, silf.bounds_cond, "len-pinning normalizes bounds ≡ guard");

        let cert = slice_index_loop_partial_faithful(&func)
            .expect("the partial-tier certificate mints for while_idx");
        assert!(
            matches!(cert.invariant, ProvenModulo3),
            "loopInvariantRule (CounterInRange 0≤i∧i≤n) must check modulo 3: {:?}",
            cert.invariant
        );
        assert!(
            matches!(cert.bounds_discharge, ProvenModulo3),
            "the BoundsCheck-assert discharge must check modulo 3: {:?}",
            cert.bounds_discharge
        );
        assert!(
            matches!(cert.counter_overflow_discharge, ProvenModulo3),
            "the counter-increment-overflow discharge must check modulo 3: {:?}",
            cert.counter_overflow_discharge
        );
        assert!(cert.is_partial_modulo_3(), "the partial tier is fully kernel-certified");

        // MANDATORY GATE 1 — termination NOT claimed (while_idx has an undischarged panic exit).
        assert!(!cert.termination_claimed(), "termination MUST NOT be claimed for while_idx");
        assert!(cert.termination.is_none(), "no total-correctness half is emitted");
        assert!(
            !function_safety_vcs_all_discharged(&func),
            "while_idx's accumulator-overflow VC is genuinely undischarged (the panic exit)"
        );

        // MANDATORY GATE 3 — the claim surface is honest.
        let claim = cert.tier_claim();
        assert!(claim.contains("PARTIAL"), "the tier claim states the partial tier: {claim}");
        assert!(
            claim.contains("termination NOT claimed"),
            "the tier claim disclaims termination: {claim}"
        );
        assert!(
            claim.contains("recognizer-trust"),
            "the tier claim documents the counter-projection trust boundary: {claim}"
        );
        eprintln!("W2 while_idx PARTIAL-TIER CLAIM: {claim}");
    }

    /// FLIP MACHINERY — when the safety VCs ARE all discharged (`total_available = true`),
    /// the SAME recognized loop's termination half (loopTotalCorrect over the projected
    /// loop) DOES kernel-check modulo 3. This is the deferred flip: the moment the
    /// accumulator-overflow VC lands, the lane upgrades to the total tier. For while_idx
    /// the gated entry keeps `total_available = false`, so this is exercised directly.
    #[test]
    fn w2_termination_flip_available_when_safety_all_discharged() {
        use crate::mirsem::RefinementVerdict::ProvenModulo3;
        let Some(func) = w2_function("while_idx") else {
            return;
        };
        let silf = extract_slice_index_loop_function(&func).expect("recognized");
        // Gated entry: termination withheld (undischarged panic exit).
        let gated = slice_index_loop_partial_faithful(&func).expect("partial cert");
        assert!(gated.termination.is_none(), "gate 1 withholds termination for while_idx");
        // Flip: with total_available=true the loopTotalCorrect half kernel-checks.
        let flipped =
            crate::mirsem::slice_index_partial_witness(&silf, true).expect("witness mints");
        assert!(
            matches!(flipped.termination, Some(ProvenModulo3)),
            "loopRankTerminates/loopTotalCorrect (rank toNat(n−i)) checks modulo 3 on the \
             projected loop: {:?}",
            flipped.termination
        );
        assert!(flipped.termination_claimed(), "the total tier claims termination");
        assert!(flipped.tier_claim().contains("TOTAL"), "the total-tier claim surface differs");
    }

    /// MANDATORY GATE 2 — DECLARED-SPEC DECLINATION. A `while_idx` body carrying a declared
    /// `ensures ret ≥ 0` (a postcondition over the HAVOCKED accumulator) must fail closed —
    /// no declared ensures may ride the partial certificate. Also covers a
    /// `ContractKind::Ensures` contract entry.
    #[test]
    fn w2_declared_ensures_declines_gate2() {
        let Some(base) = w2_function("while_idx") else {
            return;
        };
        // A declared postcondition over the return.
        let mut with_post = base.clone();
        with_post.postconditions.push(trust_types::Formula::Ge(
            Box::new(trust_types::Formula::Var("_0".into(), trust_types::Sort::Int)),
            Box::new(trust_types::Formula::Int(0)),
        ));
        assert!(
            slice_index_loop_partial_faithful(&with_post).is_none(),
            "a declared `ensures ret≥0` over the havocked accumulator MUST decline (gate 2)"
        );
        // A declared Ensures CONTRACT (even with empty parsed postconditions).
        let mut with_contract = base.clone();
        with_contract.contracts.push(trust_types::Contract {
            kind: trust_types::ContractKind::Ensures,
            span: Default::default(),
            body: "ret >= 0".into(),
        });
        assert!(
            slice_index_loop_partial_faithful(&with_contract).is_none(),
            "a declared `ensures` contract MUST decline (gate 2)"
        );
        // The RET-OVERCLAIM probe: the recognizer itself never emits a ret-value spec — the
        // exit reads the havocked accumulator, distinct from the modeled counter slot.
        let silf = extract_slice_index_loop_function(&base).expect("recognized");
        assert_ne!(
            silf.i_idx, silf.n_idx,
            "the counter and len are distinct modeled slots; the return reads NEITHER (havoc)"
        );
    }

    /// FORGERY (a) — HIDDEN SECOND INDEX. A BoundsCheck assert comparing a DIFFERENT local
    /// `j ≠ i` against the len: the recognizer declines (gate 5), AND a FORCED discharge
    /// obligation `Inv ∧ Guard(i<n) → Lt(j,n)` is kernel-REJECTED (not a tautology).
    #[test]
    fn w2_forgery_hidden_second_index() {
        use crate::mirsem::{RefinementVerdict, SemCmpOp, SemCond, SemOperand};
        let Some(func) = w2_function("while_idx") else {
            return;
        };
        let silf = extract_slice_index_loop_function(&func).expect("recognized");
        // Guard is Lt(i, n); forge a bounds cond Lt(j, n) with j a fresh non-counter slot.
        let SemOperand::Var(i_idx) = silf.guard.a else { panic!("guard LHS is a var") };
        let SemOperand::Var(n_idx) = silf.guard.b else { panic!("guard RHS is a var") };
        let j = i_idx + n_idx + 100; // a slot that is neither the counter nor the len.
        let forged = SemCond { op: SemCmpOp::Lt, a: SemOperand::Var(j), b: SemOperand::Var(n_idx) };
        let verdict = crate::mirsem::check_assert_discharge_instance(
            &silf.projected,
            &silf.guard,
            &forged,
        );
        assert!(
            matches!(verdict, RefinementVerdict::KernelRejected(_)),
            "Inv ∧ Guard(i<n) → Lt(j,n) is NOT a tautology and must be kernel-REJECTED: {verdict:?}"
        );
    }

    /// FORGERY (b) — OFF-BY-ONE Le-GUARD, and the SWAPPED/NEGATED assert probe. Both must be
    /// kernel-REJECTED at the discharge obligation (proving the implication is not a
    /// tautology of the encoding); the Le-guard also declines at the recognizer's Lt-pin.
    #[test]
    fn w2_forgery_le_guard_and_swapped_assert() {
        use crate::mirsem::{RefinementVerdict, SemCmpOp, SemCond, SemOperand};
        let Some(func) = w2_function("while_idx") else {
            return;
        };
        let silf = extract_slice_index_loop_function(&func).expect("recognized");
        let SemOperand::Var(i_idx) = silf.guard.a else { panic!() };
        let SemOperand::Var(n_idx) = silf.guard.b else { panic!() };
        // Le-guard: forced discharge `Le(i,n) → Lt(i,n)` must be REJECTED.
        let le_guard =
            SemCond { op: SemCmpOp::Le, a: silf.guard.a.clone(), b: silf.guard.b.clone() };
        let lt_assert =
            SemCond { op: SemCmpOp::Lt, a: SemOperand::Var(i_idx), b: SemOperand::Var(n_idx) };
        let v1 =
            crate::mirsem::check_assert_discharge_instance(&silf.projected, &le_guard, &lt_assert);
        assert!(
            matches!(v1, RefinementVerdict::KernelRejected(_)),
            "Le(i,n) → Lt(i,n) is unsound and must be REJECTED: {v1:?}"
        );
        // Swapped/negated assert `Ge(i,n)`: `Inv ∧ Guard(i<n) → Ge(i,n)` must be REJECTED.
        let ge_assert =
            SemCond { op: SemCmpOp::Ge, a: SemOperand::Var(i_idx), b: SemOperand::Var(n_idx) };
        let v2 = crate::mirsem::check_assert_discharge_instance(
            &silf.projected,
            &silf.guard,
            &ge_assert,
        );
        assert!(
            matches!(v2, RefinementVerdict::KernelRejected(_)),
            "Inv ∧ Guard(i<n) → Ge(i,n) must be REJECTED: {v2:?}"
        );
        // And the recognizer declines a genuine Le-guard body (Lt-pin, gate 2).
        let le_body = flip_header_guard_op(&func, trust_types::BinOp::Le);
        assert!(
            extract_slice_index_loop_function(&le_body).is_none(),
            "an `i <= s.len()` guard declines at the recognizer's Lt-pin (gate 2)"
        );
    }

    /// FORGERY — NARROW COUNTER. A `u8` counter against a `u64` len: `i+1` genuinely CAN
    /// overflow while `i < n`, so the counter-overflow discharge (goal `i+1 ≤ 255`, bound
    /// `n ≤ 2^64−1`) must be kernel-REJECTED — proving the type-bound width side condition
    /// is load-bearing. The matched-width (u64/u64) instance checks modulo 3.
    #[test]
    fn w2_forgery_narrow_counter_overflow() {
        use crate::mirsem::RefinementVerdict::{KernelRejected, ProvenModulo3};
        let Some(func) = w2_function("while_idx") else {
            return;
        };
        let silf = extract_slice_index_loop_function(&func).expect("recognized");
        // Matched widths — the honest instance discharges.
        let ok = crate::mirsem::check_counter_overflow_discharge_instance(
            &silf.projected,
            &silf.guard,
            silf.i_idx,
            silf.n_idx,
            64,
            64,
        );
        assert!(matches!(ok, ProvenModulo3), "u64 counter vs u64 len discharges: {ok:?}");
        // Narrow counter (u8) vs u64 len — genuinely can overflow, must be REJECTED.
        let bad = crate::mirsem::check_counter_overflow_discharge_instance(
            &silf.projected,
            &silf.guard,
            silf.i_idx,
            silf.n_idx,
            8,
            64,
        );
        assert!(
            matches!(bad, KernelRejected(_)),
            "a u8 counter vs u64 len must be REJECTED (i+1 can overflow while i<n): {bad:?}"
        );
    }

    /// FORGERY (f) — WRONG INVARIANT. Pinning the range invariant's upper bound to a slot
    /// the guard does NOT re-establish makes preservation ill-typed ⇒ the invariant
    /// obligation is KernelRejected ⇒ the partial witness fails closed (`None`).
    #[test]
    fn w2_forgery_wrong_invariant() {
        use crate::mirsem::SynthInvariant;
        let Some(func) = w2_function("while_idx") else {
            return;
        };
        let mut silf = extract_slice_index_loop_function(&func).expect("recognized");
        // Repoint the range's upper bound to a slot the guard `i < n` does not mention.
        let wrong_bound = silf.n_idx + 999;
        silf.projected.synth_inv =
            Some(SynthInvariant::CounterInRange { i_idx: silf.i_idx, c: 0, bound_idx: wrong_bound });
        assert!(
            crate::mirsem::slice_index_partial_witness(&silf, false).is_none(),
            "a wrong range invariant (upper bound the guard does not re-establish) is \
             KernelRejected ⇒ the partial witness fails closed"
        );
    }

    /// FORGERY (c) — A CALL IN THE BODY SPINE declines (the for-desugar `next()` loop is
    /// increment-2, not this). Plus (frame gate) a MUTABLE BORROW of the slice declines.
    #[test]
    fn w2_forgery_call_and_slice_mutation() {
        let Some(func) = w2_function("while_idx") else {
            return;
        };
        // (c) replace an in-body Assert terminator with a Call.
        let with_call = replace_first_assert_with_call(&func);
        assert!(
            extract_slice_index_loop_function(&with_call).is_none(),
            "a Call terminator in the body spine declines (gate 4)"
        );
        // frame gate: a mutable borrow of the slice parameter declines (len-pinning unsound).
        let with_mut = mutably_borrow_slice_param(&func);
        assert!(
            extract_slice_index_loop_function(&with_mut).is_none(),
            "a mutable borrow of the slice parameter declines (len-pinning frame gate, gate 3)"
        );
    }

    /// FORGERY (a') — a HIDDEN COUNTER WRITE (a third bare assignment to the counter)
    /// declines: a genuine loop counter has exactly two writes (init + the `+1` increment).
    #[test]
    fn w2_forgery_hidden_counter_write() {
        let Some(func) = w2_function("while_idx") else {
            return;
        };
        let silf = extract_slice_index_loop_function(&func).expect("recognized");
        let counter = usize::try_from(silf.i_idx).unwrap();
        let mut mutated = func.clone();
        // Append a stray third bare assignment to the counter in the exit block.
        for b in &mut mutated.body.blocks {
            if matches!(b.terminator, trust_types::Terminator::Return) {
                b.stmts.push(trust_types::Statement::Assign {
                    place: trust_types::Place::local(counter),
                    rvalue: trust_types::Rvalue::Use(trust_types::Operand::Constant(
                        trust_types::ConstValue::Uint(0, 64),
                    )),
                    span: Default::default(),
                });
            }
        }
        assert!(
            extract_slice_index_loop_function(&mutated).is_none(),
            "a third bare counter write declines (the counter must have exactly two writes)"
        );
    }

