    // --- forgery MIR mutators (test-only) --------------------------------------------

    /// Flip the loop-header guard comparison to `op` (e.g. `Lt` → `Le`) in the block
    /// whose terminator is a `SwitchInt` over the flipped temp.
    fn flip_header_guard_op(func: &VerifiableFunction, op: trust_types::BinOp) -> VerifiableFunction {
        use trust_types::{Operand, Rvalue, Statement, Terminator};
        let mut f = func.clone();
        for b in &mut f.body.blocks {
            let Terminator::SwitchInt { discr, .. } = &b.terminator else { continue };
            let (Operand::Copy(dp) | Operand::Move(dp)) = discr else { continue };
            let discr_local = dp.local;
            for s in &mut b.stmts {
                if let Statement::Assign { place, rvalue: Rvalue::BinaryOp(o, _, _), .. } = s {
                    if place.local == discr_local {
                        *o = op;
                    }
                }
            }
        }
        f
    }

    /// Replace the FIRST in-body `Assert` terminator with a `Call` (a body-spine call).
    fn replace_first_assert_with_call(func: &VerifiableFunction) -> VerifiableFunction {
        use trust_types::Terminator;
        let mut f = func.clone();
        for b in &mut f.body.blocks {
            if let Terminator::Assert { target, .. } = &b.terminator {
                let target = *target;
                b.terminator = Terminator::Call {
                    func: "core::mem::drop".into(),
                    args: vec![],
                    dest: trust_types::Place::local(0),
                    target: Some(target),
                    span: Default::default(),
                    atomic: None,
                    is_foreign: false,
                    is_unsafe_sig: false,
                    unwind: trust_types::UnwindEdge::default(),
                };
                break;
            }
        }
        f
    }

    /// Append a mutable borrow `&mut (*slice)` of the slice parameter into the entry block.
    fn mutably_borrow_slice_param(func: &VerifiableFunction) -> VerifiableFunction {
        use trust_types::{Place, Rvalue, Statement};
        let mut f = func.clone();
        // The slice param is local 1 (the sole &[T] parameter).
        if let Some(b) = f.body.blocks.first_mut() {
            b.stmts.push(Statement::Assign {
                place: Place::local(f.body.locals.len().saturating_sub(1).max(2)),
                rvalue: Rvalue::Ref { mutable: true, place: Place::local(1) },
                span: Default::default(),
            });
        }
        f
    }

    // ================================================================================
    // W2 INCREMENT-2 — ITERATOR-FOR-LOOP PARTIAL-TIER LANE tests (CLASS-NEUTRAL). The
    // ghost-counter projection over the for-desugar (sum_loop 8bb / count_pos 9bb), its
    // adversarial gates (G2-R result-provenance, CLASS-NEUTRALITY, G6 edge-target back-
    // edges, orientation pin), and every forgery probe. See the mirsem module comment.
    // ================================================================================

    /// Load `def_path` from the FRESH (offset-modeled) w2 corpus twins, or `None`.
    fn w2_offset_function(def_path: &str) -> Option<VerifiableFunction> {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("fixtures/w2-iter-offset-modeled-2026-07-20/dumps");
        if !dir.exists() {
            return None;
        }
        for entry in std::fs::read_dir(&dir).ok()?.flatten() {
            let path = entry.path();
            if path.extension().and_then(|e| e.to_str()) != Some("json") {
                continue;
            }
            let Ok(bytes) = std::fs::read(&path) else { continue };
            if let Ok(f) = decode_verifiable_function_with_authenticated_legacy_metadata(&bytes) {
                if f.def_path == def_path {
                    return Some(f);
                }
            }
        }
        None
    }

    fn empty_callees() -> std::collections::BTreeMap<String, crate::mirsem::CalleeFact> {
        std::collections::BTreeMap::new()
    }

    /// HEADLINE (INC2) — sum_loop + count_pos are recognized at the PARTIAL tier over the
    /// GHOST-COUNTER projection, obligation (I) checks modulo 3, termination is NOT claimed,
    /// and the ghost slots live OUTSIDE the MIR local index space.
    #[test]
    fn w2_iter_loop_positive_controls_partial_tier() {
        for name in ["sum_loop", "count_pos"] {
            let Some(func) = w2_function(name) else {
                eprintln!("w2 fixture absent — skipping {name}");
                return;
            };
            let callees = empty_callees();
            let ilf = extract_iter_loop_function(&func, &callees)
                .unwrap_or_else(|| panic!("{name} is the recognized iterator-for-loop fragment"));
            // GHOST-SLOT COLLISION probe: both ghost slots are outside 0..locals.len().
            let n_locals = func.body.locals.len() as u64;
            assert!(ilf.i_ghost >= n_locals, "{name}: ghost counter must be outside MIR local space");
            assert!(ilf.n_ghost > ilf.i_ghost, "{name}: ghost bound distinct + above counter");
            assert_eq!(ilf.premise, crate::mirsem::P_ITER_COUNT, "{name}: P-ITER-COUNT carried");

            let cert = iter_loop_partial_faithful(&func, &callees)
                .unwrap_or_else(|| panic!("{name} mints the partial certificate"));
            assert!(cert.is_partial_modulo_3(), "{name}: obligation (I) checks modulo 3");
            // TERMINATION OVERCLAIM probe — never minted (accumulator-overflow VC is open).
            assert!(!cert.termination_claimed(), "{name}: termination MUST NOT be claimed");
            assert!(cert.termination.is_none(), "{name}: no total-correctness half emitted");
            assert!(
                !function_safety_vcs_all_discharged(&func),
                "{name}: the accumulator-overflow VC is genuinely undischarged"
            );
            // CLAIM-SURFACE honesty — thinner than INC1, names the premise, no MIR assert.
            let claim = cert.tier_claim();
            assert!(claim.contains("PARTIAL"), "{name}: partial tier: {claim}");
            assert!(claim.contains("THINNER"), "{name}: strictly thinner than INC1: {claim}");
            assert!(claim.contains("P-ITER-COUNT"), "{name}: names the premise: {claim}");
            assert!(
                claim.contains("NO MIR assert"),
                "{name}: states NO MIR assert discharged: {claim}"
            );
            // Trust: HONEST FLOOR inc-2 (2026-07-23) — PER-FUNCTION overflow-falsifier honesty.
            // The shipped literal surfaced sum_loop's REACHABLE `s=[i32::MAX,1]` panic as
            // count_pos's own overflow evidence; count_pos returns usize (`c ≤ len ≤
            // isize::MAX < usize::MAX`), so `c+1` cannot overflow and `count_pos(&[i32::MAX,1])`
            // returns 2 and reaches Return. The corrected text is per-function.
            assert_eq!(
                ilf.accumulator_overflow,
                match name {
                    "sum_loop" => crate::mirsem::AccumulatorOverflowShape::ReachableSignedValueAdd,
                    "count_pos" => crate::mirsem::AccumulatorOverflowShape::BoundedUnsignedCounter,
                    _ => unreachable!("only sum_loop/count_pos are exercised here"),
                },
                "{name}: accumulator-overflow class"
            );
            match name {
                "sum_loop" => {
                    assert!(
                        claim.contains("REACHABLE panic")
                            && claim.contains("falsifier s=[i32::MAX,1]"),
                        "sum_loop: signed value-accumulator names its REACHABLE falsifier: {claim}"
                    );
                    assert!(
                        !claim.contains("INFEASIBLE"),
                        "sum_loop: must NOT claim infeasibility: {claim}"
                    );
                }
                "count_pos" => {
                    assert!(
                        claim.contains("INFEASIBLE on this function"),
                        "count_pos: unsigned +1 counter states its VC is infeasible: {claim}"
                    );
                    assert!(
                        !claim.contains("s=[i32::MAX,1]") && !claim.contains("panics"),
                        "count_pos: must NOT surface sum_loop's reachable panic as its own: {claim}"
                    );
                }
                _ => {}
            }
            eprintln!("W2 INC2 {name} PARTIAL-TIER CLAIM: {claim}");
        }
    }

