    /// KERNEL NON-VACUITY (unit): tamper the projected ghost model (c=1, body [i:=i+2],
    /// guard Le) — `iter_loop_partial_witness` must fail closed (`None` / KernelRejected).
    #[test]
    fn w2_iter_loop_kernel_non_vacuity() {
        use crate::mirsem::{SemBinOp, SemCmpOp, SemCond, SemCondTree, SemOperand, SemRvalue, SemStmt, SynthInvariant};
        let Some(func) = w2_function("sum_loop") else {
            return;
        };
        let ilf = extract_iter_loop_function(&func, &empty_callees()).expect("recognized");
        let (i, n) = (ilf.i_ghost, ilf.n_ghost);
        // Tampered: lower bound 1 (false at entry 0), stride +2, Le guard.
        let mut tampered = ilf.clone();
        tampered.projected = crate::mirsem::SemLoopFunction {
            cond: SemCondTree::Leaf(SemCond { op: SemCmpOp::Le, a: SemOperand::Var(i), b: SemOperand::Var(n) }),
            body: vec![SemStmt { idx: i, rvalue: SemRvalue::Bin(SemBinOp::Add, SemOperand::Var(i), SemOperand::Const(2)) }],
            inv_local: 0,
            inv_const: 0,
            synth_inv: Some(SynthInvariant::CounterInRange { i_idx: i, c: 1, bound_idx: n }),
        };
        assert!(
            crate::mirsem::iter_loop_partial_witness(&tampered, false).is_none(),
            "a tampered ghost model (c=1, +2, Le) is KernelRejected ⇒ the witness fails closed"
        );
    }

    /// G2-REQUIRES gate: a registered header `next()` fact must declare NO `requires`
    /// (`Some(vec![])`); a non-empty or unknown (`None`) precondition declines (no unnamed
    /// unestablished callee precondition may ride the certificate). A vacuous fact is fine.
    #[test]
    fn w2_iter_loop_g2_requires_gate() {
        let Some(func) = w2_function("sum_loop") else {
            return;
        };
        let next_key = "<std::slice::Iter<'_, i32> as std::iter::Iterator>::next".to_string();
        let mk = |requires| {
            let mut m = std::collections::BTreeMap::new();
            m.insert(next_key.clone(), crate::mirsem::CalleeFact {
                arg_count: 1,
                requires,
                param_names: vec![Some("self".into())],
            });
            m
        };
        // Vacuous requires — recognized.
        assert!(
            iter_loop_projection_recognized(&func, &mk(Some(vec![]))),
            "a next() fact with NO requires (vacuous) is accepted"
        );
        // Non-empty requires — declines.
        assert!(
            !iter_loop_projection_recognized(&func, &mk(Some(vec![trust_types::Formula::Bool(true)]))),
            "a next() fact with a non-empty requires declines (unnamed precondition)"
        );
        // Unknown requires — declines.
        assert!(
            !iter_loop_projection_recognized(&func, &mk(None)),
            "a next() fact with unknown (None) requires declines (fail-closed)"
        );
    }

    // --- INC2 forgery MIR mutators (test-only) ---------------------------------------

    /// The iterator local `it` — the place borrowed by the header's `_m = &mut it`.
    fn find_iter_local(func: &VerifiableFunction) -> usize {
        use trust_types::{Rvalue, Statement, Terminator};
        for b in &func.body.blocks {
            if let Terminator::Call { func: callee, .. } = &b.terminator {
                if super::is_pinned_next_callee(callee) {
                    for s in &b.stmts {
                        if let Statement::Assign { rvalue: Rvalue::Ref { mutable: true, place }, .. } = s {
                            return place.local;
                        }
                    }
                }
            }
        }
        panic!("no iterator local found");
    }

    /// Rewrite the header `next()` callee def-path to `new_callee`.
    fn rewrite_next_callee(func: &VerifiableFunction, new_callee: &str) -> VerifiableFunction {
        use trust_types::Terminator;
        let mut f = func.clone();
        for b in &mut f.body.blocks {
            if let Terminator::Call { func: callee, .. } = &mut b.terminator {
                if super::is_pinned_next_callee(callee) {
                    *callee = new_callee.to_string();
                }
            }
        }
        f
    }

    /// Rewrite the `into_iter` callee def-path to `new_callee`.
    fn rewrite_into_iter_callee(func: &VerifiableFunction, new_callee: &str) -> VerifiableFunction {
        use trust_types::Terminator;
        let mut f = func.clone();
        for b in &mut f.body.blocks {
            if let Terminator::Call { func: callee, .. } = &mut b.terminator {
                if super::is_pinned_into_iter_callee(callee) {
                    *callee = new_callee.to_string();
                }
            }
        }
        f
    }

    /// Duplicate the header `next()` Call into the entry block (a second pinned-next call).
    fn duplicate_next_call(func: &VerifiableFunction) -> VerifiableFunction {
        use trust_types::Terminator;
        let mut f = func.clone();
        let next_term = f
            .body
            .blocks
            .iter()
            .find_map(|b| match &b.terminator {
                Terminator::Call { func: callee, .. } if super::is_pinned_next_callee(callee) => {
                    Some(b.terminator.clone())
                }
                _ => None,
            })
            .expect("header next() present");
        // Re-point the entry block's terminator at a clone of the next() call (target back
        // to its own successor) — a SECOND pinned-next call in the body.
        if let Some(b) = f.body.blocks.first_mut() {
            b.terminator = next_term;
        }
        f
    }

    /// Redirect the header `next()` Call destination to a fresh (unread) junk local, leaving
    /// the dispatch switching on the ORIGINAL result local — the STALE-`_r` forgery.
    fn redirect_next_dest_to_junk(func: &VerifiableFunction) -> VerifiableFunction {
        use trust_types::{Place, Terminator};
        let mut f = func.clone();
        let junk = f.body.locals.len();
        // Clone the original result local's type for the junk local.
        let mut junk_ty = None;
        for b in &f.body.blocks {
            if let Terminator::Call { func: callee, dest, .. } = &b.terminator {
                if super::is_pinned_next_callee(callee) {
                    junk_ty = f.body.locals.get(dest.local).cloned();
                }
            }
        }
        f.body.locals.push(junk_ty.expect("result local typed"));
        for b in &mut f.body.blocks {
            if let Terminator::Call { func: callee, dest, .. } = &mut b.terminator {
                if super::is_pinned_next_callee(callee) {
                    *dest = Place::local(junk);
                }
            }
        }
        f
    }

    /// Invert the Option dispatch's targets to [[0,body],[1,exit]] (the wrong orientation).
    fn invert_option_switch(func: &VerifiableFunction) -> VerifiableFunction {
        use trust_types::Terminator;
        let mut f = func.clone();
        for b in &mut f.body.blocks {
            if let Terminator::SwitchInt { targets, exhaustive_enum_unreachable: true, .. } =
                &mut b.terminator
            {
                if targets.len() == 2 {
                    let a = targets[0].1;
                    let c = targets[1].1;
                    // Swap the block targets for values 0 and 1.
                    targets[0].1 = c;
                    targets[1].1 = a;
                }
            }
        }
        f
    }

